export default {"intro":{"ageQ":"Wie alt ist Ihr Kind?","ages":["3-5","6-8","9-12"],"genderQ":"Ist Ihr Kind ein Junge oder ein Mädchen?","genders":["Junge","Mädchen"]},"questions":[{"id":"q1","text":"Was macht Ihr Kind, wenn niemand es beschäftigt?","options":[{"scale":"builder","text":"Baut etwas oder setzt etwas zusammen"},{"scale":"storyteller","text":"Erfindet Geschichten, spricht für die Spielfiguren"},{"scale":"mover","text":"Rennt, klettert, springt"},{"scale":"artist","text":"Malt, knetet, schneidet aus"},{"scale":"inventor","text":"Nimmt Dinge auseinander oder probiert aus, was dann passiert"},{"scale":"explorer","text":"Schaut genau hin, beobachtet, sucht und findet etwas"},{"scale":"leader","text":"Holt andere dazu und denkt sich ein gemeinsames Spiel aus"},{"scale":"helper","text":"Kommt helfen oder kümmert sich um jemanden"}]},{"id":"q2","text":"Welche Spielsachen beschäftigen Ihr Kind am längsten?","options":[{"scale":"inventor","text":"Knobelspiele und Experimentierkästen"},{"scale":"helper","text":"Puppen, Kuscheltiere, Familie oder Arzt spielen"},{"scale":"leader","text":"Spiele mit Regeln, die man mit anderen spielt"},{"scale":"explorer","text":"Fundstücke von draußen: Steine, Käfer, Stöcke"},{"scale":"builder","text":"Baukästen und Bausteine"},{"scale":"storyteller","text":"Bücher, Figuren und Spielzeug zum Geschichtenspielen"},{"scale":"artist","text":"Farben, Knete, Bastelsets"},{"scale":"mover","text":"Ball, Roller, Springseil: alles für Bewegung"}]},{"id":"q3","text":"Worüber stellt Ihr Kind die meisten Warum-Fragen?","options":[{"scale":"inventor","text":"Wie Dinge und Maschinen funktionieren"},{"scale":"explorer","text":"Tiere, Natur, Weltall"},{"scale":"storyteller","text":"Was Wörter bedeuten, wie eine Geschichte ausgeht"},{"scale":"helper","text":"Warum Menschen traurig, wütend oder froh sind"}]},{"id":"q4","text":"Was wählt Ihr Kind am Bildschirm, wenn es selbst entscheiden darf?","options":[{"scale":"builder","text":"Spiele, in denen man Welten und Städte baut"},{"scale":"artist","text":"Malen, Musik, Bastelvideos"},{"scale":"mover","text":"Sport, Tanzen, Tricks"},{"scale":"leader","text":"Wettkämpfe und Challenges"}]},{"id":"q5","text":"Was macht Ihr Kind auf dem Spielplatz?","options":[{"scale":"mover","text":"Klettert sofort ganz nach oben"},{"scale":"leader","text":"Holt Kinder zusammen und denkt sich ein Spiel aus"},{"scale":"explorer","text":"Erkundet jede Ecke und findet etwas"},{"scale":"helper","text":"Kümmert sich um Kleinere, teilt"}]},{"id":"q6","text":"Welche Bücher und Geschichten mag Ihr Kind?","options":[{"scale":"storyteller","text":"Märchen und Abenteuer mit Helden"},{"scale":"inventor","text":"Sachbücher und „Wie funktioniert das?“"},{"scale":"artist","text":"Solche mit schönen Bildern zum Anschauen"},{"scale":"builder","text":"Über Fahrzeuge, Technik, Baustellen"}]},{"id":"q7","text":"Welches Geschenk würde Ihr Kind selbst wählen?","options":[{"scale":"builder","text":"Einen Baukasten"},{"scale":"artist","text":"Ein Kreativset oder ein Instrument"},{"scale":"inventor","text":"Einen Experimentierkasten"},{"scale":"mover","text":"Einen Ball, Roller oder ein Fahrrad"}]},{"id":"q8","text":"Worauf ist Ihr Kind am meisten stolz?","options":[{"scale":"leader","text":"Gewonnen oder das Sagen gehabt zu haben"},{"scale":"helper","text":"Jemandem geholfen zu haben"},{"scale":"storyteller","text":"Etwas vorgetragen, erzählt oder andere zum Lachen gebracht zu haben"},{"scale":"explorer","text":"Etwas Neues gefunden oder entdeckt zu haben"}]},{"id":"q9","text":"Ein Lieblingsspielzeug geht kaputt. Was macht Ihr Kind?","options":[{"scale":"builder","text":"Versucht, es zu reparieren"},{"scale":"inventor","text":"Nimmt es auseinander, um hineinzuschauen"},{"scale":"artist","text":"Macht etwas anderes daraus"},{"scale":"storyteller","text":"Erfindet eine Geschichte dazu, was passiert ist"}]},{"id":"q10","text":"Eine neue Kindergruppe. Wie verhält sich Ihr Kind?","options":[{"scale":"leader","text":"Schlägt vor, was gespielt wird"},{"scale":"helper","text":"Sucht sich ein Kind und freundet sich mit ihm an"},{"scale":"explorer","text":"Beobachtet erst und schaut sich um"},{"scale":"mover","text":"Rennt sofort mit"}]},{"id":"q11","text":"Eine Aufgabe klappt nicht. Was macht Ihr Kind?","options":[{"scale":"inventor","text":"Probiert einen anderen Weg"},{"scale":"builder","text":"Macht Schritt für Schritt weiter, bis es klappt"},{"scale":"leader","text":"Holt andere dazu"},{"scale":"storyteller","text":"Denkt laut und bespricht es"}]},{"id":"q12","text":"Ihr Kind verliert ein Spiel. Was passiert dann?","options":[{"scale":"mover","text":"Will sofort eine Revanche"},{"scale":"leader","text":"Diskutiert über die Regeln, verhandelt"},{"scale":"helper","text":"Gratuliert, achtet auf die anderen"},{"scale":"artist","text":"Geht und macht sein eigenes Ding"}]},{"id":"q13","text":"Ein freier Tag. Was würde Ihr Kind wählen?","options":[{"scale":"explorer","text":"Wald, Zoo oder Museum"},{"scale":"mover","text":"Schwimmbad, Trampolin, Sport"},{"scale":"artist","text":"Basteln, Malen, Musik"},{"scale":"storyteller","text":"Theater, Kino, Bücher"}]},{"id":"q14","text":"Jemand in der Nähe weint. Was macht Ihr Kind?","options":[{"scale":"helper","text":"Geht hin und tröstet"},{"scale":"leader","text":"Holt einen Erwachsenen, übernimmt die Führung"},{"scale":"storyteller","text":"Fragt nach, was passiert ist"},{"scale":"inventor","text":"Versucht, die Ursache zu beheben"}]},{"id":"q15","text":"Sie packen für einen Ausflug. Wie bereitet sich Ihr Kind vor?","options":[{"scale":"builder","text":"Packt alles ordentlich ein"},{"scale":"explorer","text":"Fragt, wohin es geht und was es dort gibt"},{"scale":"artist","text":"Sucht Outfit und Lieblingssachen aus"},{"scale":"mover","text":"Kann nicht stillsitzen, steht schon an der Tür"}]},{"id":"q16","text":"Ihr Kind bekommt eine Kiste mit verschiedenen Teilen. Was macht es?","options":[{"scale":"builder","text":"Baut sofort etwas"},{"scale":"inventor","text":"Sortiert und testet, wofür was ist"},{"scale":"helper","text":"Überlegt, wem es daraus ein Geschenk basteln kann"},{"scale":"explorer","text":"Betrachtet jedes Teil und fragt, woher es kommt"}]}],"sliders":{"labels":["Selten","Manchmal","Oft","Fast immer","Immer"],"items":[{"id":"energy","text":"Mein Kind spielt lieber in Bewegung als im Sitzen"},{"id":"boldness","text":"Geht mutig auf Neues zu: Orte, Menschen, Aktivitäten"},{"id":"persistence","text":"Bringt Angefangenes zu Ende, auch wenn es schwer ist"},{"id":"sensitivity","text":"Spürt die Stimmung anderer und empfindet intensiv"},{"id":"sociability","text":"Findet leicht Anschluss und ist gern unter Menschen"},{"id":"pace","text":"Mag es schnell und wartet ungern"}]},"goal":{"text":"Was möchten Sie vor allem herausfinden?","options":[{"id":"activity","text":"Welcher Kurs oder Verein passt"},{"id":"strengths","text":"Worin mein Kind am stärksten ist"},{"id":"future","text":"Was ich mit meinem Kind als Nächstes ausprobieren kann"},{"id":"character","text":"Wie ich mein Kind besser erreiche"}]},"types":{"builder":{"name":"Baumeister","nameF":"Baumeisterin","tagline":"Denkt mit den Händen und sieht, wie aus Teilen ein Ganzes wird","careers":"Ingenieurwesen, Architektur, Mechanik, Schreinerei"},"inventor":{"name":"Erfinder","nameF":"Erfinderin","tagline":"Will wissen, wie alles funktioniert, und probiert es auf eigene Art","careers":"Wissenschaft, Softwareentwicklung, Datenanalyse, Forschung"},"storyteller":{"name":"Erzähler","nameF":"Erzählerin","tagline":"Denkt in Worten und Geschichten und zieht andere in den Bann","careers":"Journalismus, Schreiben, Jura, Schauspiel"},"artist":{"name":"Künstler","nameF":"Künstlerin","tagline":"Sieht Schönheit und Details und erschafft Eigenes","careers":"Design, Illustration, Musik, Architektur"},"explorer":{"name":"Entdecker","nameF":"Entdeckerin","tagline":"Beobachtet, sammelt Fakten und schaut nach, was hinter der Ecke liegt","careers":"Biologie, Tiermedizin, Geografie, Umweltwissenschaft"},"leader":{"name":"Anführer","nameF":"Anführerin","tagline":"Ergreift die Initiative, verhandelt und nimmt andere mit","careers":"Unternehmertum, Management, Eventorganisation, Coaching"},"helper":{"name":"Helfer","nameF":"Helferin","tagline":"Spürt, wie es anderen geht, und ist sofort zur Stelle","careers":"Medizin, Lehramt, Psychologie, Tiermedizin"},"mover":{"name":"Wirbelwind","nameF":"Wirbelwind","tagline":"Denkt in Bewegung: probiert erst mit dem Körper, erklärt später","careers":"Leistungssport, Training, Choreografie, Rettungsdienst"}},"shade":{"swift":{"m":"flink","f":"flink"},"calm":{"m":"bedacht","f":"bedacht"}},"disclaimer":"Beruht auf Beobachtungen der Eltern. Keine psychologische oder medizinische Beurteilung.","report":{"builder":{"about":"{name} denkt mit den Händen. Dinge werden verständlich, sobald sie gebaut, zerlegt oder zusammengesetzt sind. Kinder mit diesem Profil sehen, wie aus Teilen ein Ganzes wird, und bleiben dran, bis die Konstruktion steht.","hooks":"Das fesselt: Aufgaben mit einem klaren Ergebnis zum Anfassen. Das langweilt schnell: lange Erklärungen, bei denen es nichts zu tun gibt, und Beschäftigungen, bei denen nichts entsteht.","strengths":["Räumliches Denken: kann sich vorstellen, wie Teile zusammenpassen","Geduld für schrittweises Arbeiten","Bringt Dinge zu einem Ergebnis, das funktioniert"],"grow":"In Worte fassen, was gerade entsteht und warum. Bitten Sie um eine Führung durch das Gebaute.","say":["„Erzähl mir, wie du darauf gekommen bist“","„Was war beim Bauen am schwierigsten?“","„Was würdest du beim nächsten Mal ändern?“"],"ages":{"3-5":"große Bausteine, Spielen mit Sand und Wasser, Bauen aus Kartons","6-8":"Bausätze nach Anleitung, Origami, einfache Modelle, Robotik für Einsteiger","9-12":"Modellbau, ein 3D-Stift oder eine 3D-Design-App, eine Holz- oder Bastelwerkstatt"},"plan":["Woche 1. Bauen nach Plan: ein Modell nach einem Bild nachbauen, von Anfang bis Ende.","Woche 2. Die eigene Version: das Modell verändern und verbessern.","Woche 3. Eine Herausforderung mit Vorgaben: eine Papierbrücke, die ein Buch trägt.","Woche 4. Ein Familienprojekt: etwas Nützliches für zu Hause bauen und vorstellen."],"sayAge":{"3-5":["„Zeig mir, wie du das gebaut hast“","„Welches Teil war am schwierigsten?“","„Und was möchtest du morgen bauen?“"],"9-12":["„Erklär mir, wie dein Entwurf funktioniert“","„Welches Problem hat am längsten gedauert?“","„Wie würde Version zwei aussehen?“"]},"planAge":{"3-5":["Woche 1. Ein Turm aus großen Klötzen oder Kartons. Starten Sie mit der heutigen Spielidee.","Woche 2. Nachbauen: Sie stapeln drei Klötze, Ihr Kind baut es nach.","Woche 3. Eine Brücke aus Kissen, über die ein Kuscheltier laufen kann.","Woche 4. Ein Haus für ein Spielzeug: zusammen bauen und der Familie zeigen."],"9-12":["Woche 1. Erst skizzieren, dann aus Karton bauen. Starten Sie mit der heutigen Spielidee.","Woche 2. Version zwei: das Modell testen, die Schwachstelle finden, verbessern.","Woche 3. Aufgabe mit Vorgaben: der höchste Turm aus zehn Blatt Papier, ohne Kleber.","Woche 4. Ein echtes Problem zu Hause: Ihr Kind wählt es aus und baut eine Lösung."]}},"inventor":{"about":"{name} will wissen, wie alles funktioniert, und prüft es selbst nach. Eine fertige Antwort ist weniger spannend als das eigene Experiment. Kinder mit diesem Profil probieren aus, irren sich und versuchen es auf einem anderen Weg.","hooks":"Das fesselt: Rätsel, Experimente, die Frage „Was passiert, wenn …?“. Das langweilt schnell: immer das Gleiche wiederholen und etwas tun, „weil man das eben so macht“.","strengths":["Neugier und kluge Fragen","Logik: erkennt Ursache und Wirkung","Keine Angst vor Fehlern, sucht einen anderen Weg"],"grow":"Dinge zu Ende bringen. Es gibt mehr Ideen als fertige Projekte. Vereinbaren Sie immer nur ein kleines Ziel auf einmal.","say":["„Wie könntest du das überprüfen?“","„Gute Frage, das finden wir zusammen heraus“","„Ein Fehler ist auch ein Ergebnis. Was hat er dir gezeigt?“"],"ages":{"3-5":"Wasserspiele mit Trichtern und Bechern, Sortierspiele, einfache Puzzles","6-8":"Experimentierkästen, Schach, Logikspiele, erste Schritte im Programmieren","9-12":"Programmieren, Elektronik, eine Forscher-AG, Knobelwettbewerbe"},"plan":["Woche 1. Jeden Tag ein Experiment von 10 Minuten: was sinkt, was rollt, was sich auflöst.","Woche 2. Ein Tagebuch „Ich dachte, aber es kam so“: vorher die Vermutung, danach das Ergebnis.","Woche 3. Logik: ein Spiel oder Rätsel, jeden Tag etwas schwieriger.","Woche 4. Das eigene Experiment: eine Frage wählen, sie prüfen und der Familie vorstellen."],"sayAge":{"3-5":["„Was glaubst du, was passiert?“","„Gute Frage! Das probieren wir gleich aus“","„Hoppla, das war eine Überraschung! Noch einmal?“"],"9-12":["„Womit ließe sich das widerlegen?“","„Das weiß ich auch nicht. Wo schauen wir nach?“","„Das Ergebnis kam unerwartet. Wie erklärst du es dir?“"]},"planAge":{"3-5":["Woche 1. Was rollt und was rutscht von einer Kissenrampe? Starten Sie mit der heutigen Spielidee.","Woche 2. Erst raten: „Rollt es?“ Ihr Kind sagt es laut, dann prüfen Sie es zusammen.","Woche 3. Spielzeug sortieren: groß und klein, weich und hart, in zwei Kisten.","Woche 4. Die eigene Frage: Ihr Kind fragt, Sie probieren es zusammen mit Spielzeug aus."],"9-12":["Woche 1. Jeden Tag eine Frage und ein kurzer Test zu Hause. Starten Sie mit der heutigen Spielidee.","Woche 2. Ein Laborheft: Vermutung, Vorgehen, Ergebnis und was beim nächsten Mal anders wird.","Woche 3. Logik: Ihr Kind erfindet ein Rätsel oder einen Code für die Familie.","Woche 4. Ein fairer Test: nur eine Sache ändern, dreimal messen, das Ergebnis vorstellen."]}},"storyteller":{"about":"{name} denkt in Wörtern und Geschichten. Was als Geschichte erzählt wird, bleibt im Gedächtnis, und aus einem gewöhnlichen Tag wird eine Erzählung. Kindern mit diesem Profil ist es wichtig, dass man ihnen zuhört.","hooks":"Das fesselt: Bücher, Gespräche, Rollenspiele, Auftritte. Das langweilt schnell: stille Einzelarbeit und Aufgaben ohne Geschichte und ohne Figuren.","strengths":["Reiche Sprache und ein Gedächtnis für Geschichten","Fantasie: erfindet Welten und Figuren","Kann begeistern und überzeugen"],"grow":"Genauso gern zuhören wie reden. Spielen Sie „Interview“: Ihr Kind stellt die Fragen.","say":["„Erzähl, wie es weiterging“","„Das Wort, das du da gewählt hast, gefällt mir“","„Wie hat sich die Figur gefühlt?“"],"ages":{"3-5":"Vorlesen mit Fragen, Puppentheater, Gutenachtgeschichten erfinden","6-8":"Theatergruppe, einen Comic oder ein kleines Buch gestalten, eine Fremdsprache","9-12":"Debattierclub, Schülerzeitung oder Blog, kreatives Schreiben oder Theater"},"plan":["Woche 1. Geschichte des Tages: jeden Abend drei Sätze über das wichtigste Ereignis.","Woche 2. Das eigene Buch: 6 Seiten mit Bildern und Text.","Woche 3. Ein Interview: Großeltern, Nachbarn oder Freunde befragen und nacherzählen.","Woche 4. Ein Auftritt: die Geschichte der Familie vorführen, mit Rollen oder Puppen."],"sayAge":{"3-5":["„Und was ist dann passiert?“","„Was für ein lustiges Wort! Sag es noch mal“","„Ist der Hase froh oder traurig?“"],"9-12":["„Ich will wissen, wie es ausgeht“","„Dieser Satz ist mir im Kopf geblieben“","„Warum handelt die Figur so?“"]},"planAge":{"3-5":["Woche 1. Abends erzählen: Was war heute am schönsten? Starten Sie mit der heutigen Spielidee.","Woche 2. Ein Bilderbuch: drei Bilder malen und dazu erzählen.","Woche 3. Weitererzählen: Ihr Kind erzählt einem Kuscheltier, was heute los war.","Woche 4. Ein Auftritt: ein Lieblingsmärchen mit Kuscheltieren der Familie vorspielen."],"9-12":["Woche 1. Jeden Tag eine Geschichte in fünf Sätzen. Starten Sie mit der heutigen Spielidee.","Woche 2. Kurzgeschichte oder Comic: Entwurf und Überarbeitung.","Woche 3. Ein echtes Interview: fünf Fragen vorbereiten, aufnehmen, aufschreiben.","Woche 4. Vor Publikum: eine Podcastfolge, ein Kurzfilm oder eine Lesung für die Familie."]}},"artist":{"about":"{name} bemerkt, was anderen entgeht: Farbe, Form, Klang, Stimmung. Kinder mit diesem Profil denken in Bildern und wollen es auf ihre eigene Art machen, nicht wie in der Vorlage.","hooks":"Das fesselt: die Freiheit, Material und Ergebnis selbst zu wählen. Das langweilt schnell: Aufgaben nach Schablone, Eile und Bewertungen nach „richtig“ oder „falsch“.","strengths":["Ein scharfer Blick für Details","Eigene, originelle Ideen","Kann lange in die eigene Arbeit vertieft bleiben"],"grow":"Die eigene Arbeit anderen zeigen und Anmerkungen ruhig annehmen. Beginnen Sie mit: „Was gefällt dir selbst daran?“","say":["„Erzähl mir, was hier passiert“","„Ich sehe, wie viel Arbeit in diesen Details steckt“","„Wie hast du diese Farben ausgesucht?“"],"ages":{"3-5":"Farben und Fingermalen, Knete, Musik und Tanzen dazu","6-8":"Malkurs, ein Musikinstrument, Basteln mit Alltagsmaterialien","9-12":"Zeichnen oder digitale Illustration, Foto und Video, eine Band oder ein Chor"},"plan":["Woche 1. Jeden Tag ein Material: Bleistift, Farbe, Knete, Papier, Naturmaterialien.","Woche 2. Ein Thema, fünf Wege: zeichnen, formen, fotografieren, als Collage kleben, vorspielen.","Woche 3. Ein großes Werk: ein Projekt für die ganze Woche, 15 Minuten am Tag.","Woche 4. Eine Ausstellung zu Hause: die besten Arbeiten auswählen, beschriften und die Familie einladen."],"sayAge":{"3-5":["„Erzähl mir von deinem Bild“","„Du hast das ganze Blatt mit Farbe gefüllt!“","„Welche Farbe magst du am liebsten?“"],"9-12":["„Was wolltest du hier ausdrücken?“","„Man sieht, wie bewusst du die Details gewählt hast“","„Warum hast du diesen Stil gewählt?“"]},"planAge":{"3-5":["Woche 1. Jeden Tag ein Material: Wachsstifte, Papier, Knete. Starten Sie mit der heutigen Spielidee.","Woche 2. Ein Thema, drei Wege: eine Katze malen, kneten und als Katze spielen.","Woche 3. Ein großes Bild: ein großes Blatt auf dem Boden, jeden Tag ein bisschen.","Woche 4. Eine Ausstellung zu Hause: Ihr Kind wählt Bilder aus und zeigt sie der Familie."],"9-12":["Woche 1. Jeden Tag eine Skizze nach der Natur, 10 Minuten. Starten Sie mit der heutigen Spielidee.","Woche 2. Ein Motiv, fünf Techniken: Linie, Schattierung, Collage, Foto, digital.","Woche 3. Eine Serie: drei Arbeiten zu einer Idee, von Ihrem Kind geplant.","Woche 4. Eine Mappe: die stärksten Arbeiten auswählen, betiteln und der Familie präsentieren."]}},"explorer":{"about":"{name} schaut erst und handelt dann. Kinder mit diesem Profil sammeln Fakten, erkennen Muster und merken sich erstaunliche Einzelheiten über Tiere, Planeten oder Dinosaurier.","hooks":"Das fesselt: alles Neue, Lebendige und Echte, Sammlungen und Karten. Das langweilt schnell: drinnen bleiben und Dinge lernen, die man nicht sehen kann.","strengths":["Beobachtungsgabe","Ein Gedächtnis für Fakten und Details","Selbstständigkeit: kann sich allein beschäftigen"],"grow":"In eine neue Gruppe hineinfinden. Dafür braucht es Zeit zum Umschauen. Drängen Sie Ihr Kind nicht. Geben Sie ihm 10 Minuten zum Zuschauen.","say":["„Was hast du heute Neues bemerkt?“","„Zeig mir, was du gefunden hast“","„Lass uns prüfen, ob das stimmt“"],"ages":{"3-5":"Spaziergänge mit der Lupe, eine Pflanze pflegen, Tierbücher","6-8":"eine Natur-AG, Sammlungen, Pfadfinder, Wandern","9-12":"Biologie oder Astronomie, Orientierungslauf, ehrenamtliche Hilfe im Tierheim"},"plan":["Woche 1. Entdeckerspaziergänge: jeden Tag drei neue Dinge auf einem bekannten Weg finden.","Woche 2. Eine Sammlung: 10 Fundstücke sammeln, ordnen und beschriften.","Woche 3. Beobachtung: eine Woche lang ein Thema (eine Pflanze, Vögel, das Wetter) mit einer täglichen Notiz.","Woche 4. Eine Expedition: einen Familienausflug planen und die Führung übernehmen."],"sayAge":{"3-5":["„Was hast du heute draußen gesehen?“","„Zeig mir mal deinen Schatz“","„Komm, wir schauen mal nach“"],"9-12":["„Was ist dir heute aufgefallen?“","„Zeig mir, was du herausgefunden hast“","„Wie können wir die Quelle prüfen?“"]},"planAge":{"3-5":["Woche 1. Farbenjagd: drei rote Dinge beim Spaziergang finden. Starten Sie mit der heutigen Spielidee.","Woche 2. Eine Schatzkiste: fünf Blätter oder Zapfen, nach Größe geordnet.","Woche 3. Fensterblick: jeden Tag zusammen hinausschauen und sagen, wie das Wetter ist.","Woche 4. Eine kleine Expedition: Ihr Kind führt alle auf dem Weg zum Park."],"9-12":["Woche 1. Eine Karte der Umgebung: jeden Tag ein neues Detail. Starten Sie mit der heutigen Spielidee.","Woche 2. Ein Bestimmungsheft: 10 Arten vor Ort fotografieren und benennen.","Woche 3. Eine Datenwoche: täglich eine Sache erfassen (Wetter, Vögel, Verkehr) und als Diagramm zeichnen.","Woche 4. Eine Expedition: Ihr Kind plant Route, Budget und Zeitplan des Ausflugs."]}},"leader":{"about":"{name} erkennt schnell, was zu tun ist, und holt dafür andere zusammen. Kinder mit diesem Profil schlagen Regeln vor, verteilen Rollen und achten auf das gemeinsame Ergebnis.","hooks":"Das fesselt: ein Ziel, ein Team und Mitsprache bei Entscheidungen. Das langweilt schnell: Aufgaben ohne Wahl und Situationen, in denen nichts vom eigenen Beitrag abhängt.","strengths":["Initiative: macht den ersten Schritt","Kann verhandeln","Übernimmt Verantwortung für das Ergebnis"],"grow":"Nachgeben und verlieren können. Lassen Sie Ihr Kind ab und zu die „rechte Hand“ sein, während jemand anderes das Sagen hat.","say":["„Wie hast du entschieden, wer was macht?“","„Was denken die anderen? Frag sie“","„Heute leitest du das“"],"ages":{"3-5":"Spiele mit Regeln, zu Hause „Helferkind des Tages“ sein, einfache Mannschaftsspiele","6-8":"Mannschaftssport, Strategiespiele am Tisch, Pfadfinder","9-12":"Mannschaftsführung, Schülervertretung, ein eigenes kleines Projekt oder ein Verkaufsstand"},"plan":["Woche 1. Eine Aufgabe zu Hause, für die Ihr Kind eine Woche lang allein zuständig ist.","Woche 2. Spieleabend der Familie: Ihr Kind erklärt die Regeln und leitet das Spiel.","Woche 3. Ein Miniprojekt: einen Ausflug oder ein Fest für zwei oder drei Personen organisieren.","Woche 4. Rollentausch: eine Woche lang helfen und dem Plan von jemand anderem folgen."],"sayAge":{"3-5":["„Wer fängt an? Du darfst bestimmen“","„Frag mal, was die anderen spielen wollen“","„Heute gehst du voran“"],"9-12":["„Wie hast du die Aufgaben verteilt?“","„Wessen Meinung fehlt dir noch?“","„Das entscheidest du“"]},"planAge":{"3-5":["Woche 1. Eine kleine tägliche Aufgabe gehört Ihrem Kind. Starten Sie mit der heutigen Spielidee.","Woche 2. Alle mir nach: Ihr Kind macht eine Bewegung vor, alle machen sie nach.","Woche 3. Ein Picknick für Kuscheltiere: Ihr Kind wählt die Gäste und die Sitzplätze.","Woche 4. Abwechseln: Jetzt führen Sie das Spiel, und Ihr Kind macht es Ihnen nach."],"9-12":["Woche 1. Ein Bereich zu Hause, den Ihr Kind selbst führt. Starten Sie mit der heutigen Spielidee.","Woche 2. Familienrat: Ihr Kind legt die Themen fest und leitet das Gespräch.","Woche 3. Ein echtes Projekt: einen Familienabend mit Budget und verteilten Rollen planen.","Woche 4. Rollentausch: Ihr Kind arbeitet im Projekt von jemand anderem als Teammitglied mit."]}},"helper":{"about":"{name} spürt die Stimmung anderer, bevor sie ein Wort sagen. Kindern mit diesem Profil sind Beziehungen wichtig: Sie merken sich, wer was mag, und sorgen dafür, dass es allen gut geht.","hooks":"Das fesselt: etwas mit jemandem und für jemanden tun. Das langweilt schnell: Konkurrenz und Beschäftigungen, bei denen alle für sich allein sind.","strengths":["Einfühlungsvermögen: versteht, wie andere sich fühlen","Verlässlichkeit und Fürsorge","Kann Streit schlichten und Menschen zusammenbringen"],"grow":"Nein sagen und die eigenen Wünsche benennen. Fragen Sie öfter: „Und was möchtest du?“","say":["„Du hast gemerkt, dass jemand traurig war. Das ist wichtig“","„Und was möchtest du?“","„Du kannst Nein sagen und trotzdem befreundet bleiben“"],"ages":{"3-5":"Arzt und Familie spielen, ein Haustier oder eine Pflanze versorgen, in der Küche helfen","6-8":"Gruppen mit wenigen Kindern, Tiere versorgen, Erste Hilfe für Kinder","9-12":"Ehrenamt, Jüngere begleiten und anleiten, Psychologie oder Biologie"},"plan":["Woche 1. Jeden Tag eine gute Tat und abends ein kurzes Gespräch darüber, wie es war.","Woche 2. Etwas Lebendiges versorgen: Eine Pflanze gießen oder ein Haustier füttern wird die tägliche Aufgabe Ihres Kindes, und Sie schauen nach.","Woche 3. Meine Wünsche: Jeden Tag gehört eine Entscheidung allein Ihrem Kind (Abendessen, Spiel, Weg).","Woche 4. Ein selbst gemachtes Geschenk: für einen nahen Menschen planen und anfertigen."],"sayAge":{"3-5":["„Du hast den Teddy getröstet. Das war lieb von dir“","„Und welches willst du?“","„Du darfst auch sagen: jetzt nicht, später“"],"9-12":["„Du hast gemerkt, was gebraucht wurde. Das kann nicht jeder“","„Und was brauchst du?“","„Nein sagen heißt nicht, jemanden im Stich zu lassen“"]},"planAge":{"3-5":["Woche 1. Jeden Tag gemeinsam einmal helfen. Starten Sie mit der heutigen Spielidee.","Woche 2. Etwas Lebendiges versorgen: Ihr Kind hilft Ihnen jeden Tag, eine Pflanze zu gießen, und schaut sie mit Ihnen an.","Woche 3. Meine Wünsche: Jeden Tag wählt Ihr Kind eins von zweien (Becher, Buch).","Woche 4. Ein Geschenk: ein Bild für einen nahen Menschen malen und selbst überreichen."],"9-12":["Woche 1. Jeden Tag eine hilfreiche Tat nach eigener Wahl. Starten Sie mit der heutigen Spielidee.","Woche 2. Echte Verantwortung: Ein Haustier, eine Pflanze oder die Vorlesezeit für ein jüngeres Kind liegt die ganze Woche bei Ihrem Kind.","Woche 3. Meine Grenzen: Jeden Tag äußert Ihr Kind einen eigenen Wunsch oder ein klares Nein.","Woche 4. Ein Hilfsprojekt: etwas für Nachbarn oder Verwandte planen und umsetzen."]}},"mover":{"about":"{name} denkt in Bewegung. Verstehen und Merken fallen leichter, wenn der Körper mitmacht: zeigen, ausprobieren, wiederholen. Kinder mit diesem Profil haben mehr Energie, als ein gewöhnlicher Tag verlangt.","hooks":"Das fesselt: Tempo, Herausforderung, neue Tricks. Das langweilt schnell: lange sitzen und zuhören, ohne aufstehen zu dürfen.","strengths":["Koordination und Geschicklichkeit","Mut, Neues auszuprobieren","Ausdauer beim Üben einer Fertigkeit"],"grow":"Ruhige Beschäftigungen. Erst darf sich Ihr Kind bewegen: Nach 10 aktiven Minuten fällt das Stillsitzen leichter.","say":["„Zeig mir, wie du das machst“","„Ich habe gesehen, wie oft du es versucht hast, bis es geklappt hat“","„Erst toben, dann setzen wir uns hin“"],"ages":{"3-5":"Laufrad, Hindernisparcours zu Hause, Schwimmen, Tanzen","6-8":"Turnen, Schwimmen, Mannschaftsspiele, Kampfsport","9-12":"ein Verein in der gewählten Sportart, Klettern, eine Tanzgruppe"},"plan":["Woche 1. 10 Minuten Bewegung am Tag: ein neues Spiel oder eine neue Übung.","Woche 2. Eine Fertigkeit: einen Trick wählen (Seilspringen, Balancieren, ein Balltrick) und die ganze Woche üben.","Woche 3. Schnuppern: eine neue Sportart zu Hause oder draußen testen.","Woche 4. Vorführung: Ihr Kind zeigt der Familie das Gelernte und wählt die nächste Fertigkeit."],"sayAge":{"3-5":["„Zeig mir, wie du hüpfst“","„Du probierst es immer wieder. Und jetzt klappt es!“","„Erst hüpfen wie Frösche, dann vorlesen“"],"9-12":["„Bring mir bei, wie das geht“","„Man sieht, wie viel Training in dieser Bewegung steckt“","„Beweg dich kurz, danach geht es weiter“"]},"planAge":{"3-5":["Woche 1. Jeden Tag 5 Minuten Tiergänge. Starten Sie mit der heutigen Spielidee.","Woche 2. Eine Fertigkeit: über einen Schal balancieren, der auf dem Boden liegt, jeden Tag ein bisschen.","Woche 3. Etwas Neues: ein Parcours aus Kissen im Wohnzimmer.","Woche 4. Vorführung: Ihr Kind zeigt der Familie die Lieblingsbewegung und verbeugt sich."],"9-12":["Woche 1. 10 Minuten Training am Tag, selbst geplant. Starten Sie mit der heutigen Spielidee.","Woche 2. Eine Fertigkeit: Ihr Kind setzt sich ein messbares Ziel (Jonglieren, Handstand, Sprint) und notiert die Fortschritte.","Woche 3. Schnuppern: eine neue Sportart per Video zu Hause testen.","Woche 4. Coaching: Ihr Kind bringt der Familie das Gelernte bei und setzt sich das nächste Ziel."]}}},"cards":[{"id":"builder-1","scale":"builder","art":"📄🌉🧸","title":"Brücke aus Papier","task":{"3-5":"Legen Sie ein Blatt Papier zwischen zwei Bücher. Wie viele Spielsachen trägt es? Falten Sie das Blatt wie einen Fächer und probieren Sie es noch einmal.","6-8":"Bauen Sie aus einem Blatt Papier eine Brücke zwischen zwei Büchern. Ziel: Sie trägt 10 Münzen. Ohne Klebeband und ohne Schere.","9-12":"Drei Blatt Papier und Klebeband. Ihr Kind baut eine 30 cm lange Brücke, die ein Buch trägt. Erst einen Plan zeichnen, dann mit dem Ergebnis vergleichen."},"why":"Ihr Kind erlebt selbst, dass die Form ein schwaches Material stabil macht. Das ist der Kern des Ingenieurdenkens.","tip":"Verraten Sie die Lösung nicht. Fragen Sie: „Was glaubst du, warum hängt es durch? Was könnten wir ändern?“","need":{"3-5":"ein Blatt Papier, zwei Bücher, 5–6 leichte Spielsachen","6-8":"ein Blatt Papier, zwei Bücher, 10 Münzen oder Radiergummis","9-12":"drei Blatt Papier, Klebeband, Lineal, ein Buch"},"steps":{"3-5":["Legen Sie die Bücher nebeneinander, eine Erwachsenenhand breit auseinander, und das Blatt als Brücke darüber.","Stellen Sie die Spielsachen einzeln auf die Brücke und zählen Sie laut mit, wie viele sie trägt.","Falten Sie das Blatt gemeinsam wie eine Ziehharmonika und legen Sie es wieder auf.","Probieren Sie es noch einmal und vergleichen Sie: Wie viele waren es vorher, wie viele jetzt?"],"6-8":["Die Aufgabe: Eine Brücke aus einem Blatt soll 10 Münzen tragen. Ohne Klebeband und ohne Schere.","Erster Versuch: Ihr Kind legt das Blatt einfach auf und testet.","Geben Sie 3 Minuten zum Ausprobieren: knicken, falten und rollen sind erlaubt.","Testen Sie die beste Variante und lassen Sie sich erklären, warum sie hält."],"9-12":["Die Vorgabe: Eine 30 cm lange Brücke soll ein Buch tragen.","Zuerst zeichnet Ihr Kind einen Plan: welche Form, wo die Stützen stehen.","Bauen nach Plan, 5 Minuten.","Test mit dem Buch. Vergleichen Sie Plan und Ergebnis: Was musste geändert werden und warum?"]}},{"id":"builder-2","scale":"builder","art":"🧱🗼📏","title":"Der höchste Turm","task":{"3-5":"Bauen Sie einen Turm aus Bausteinen oder Plastikbechern, höher als das Knie Ihres Kindes. Dann höher als die Hüfte.","6-8":"Nehmen Sie 20 Dinge aus der Küche (Becher, Schwämme, Schachteln). Der Turm soll höher werden als der Tisch. Umgefallen? Suchen Sie das Stockwerk, das nachgegeben hat.","9-12":"Ein Turm nur aus Papier und Klebeband, ohne Stütze an der Wand. Ziel: 1 Meter. Messen, den Rekord notieren und versuchen, ihn zu übertreffen."},"why":"Ein Turm lehrt Gleichgewicht, Geduld und Fehlersuche: Nicht „alles“ ist eingestürzt, eine Etage hat nachgegeben.","tip":"Wenn der Turm fällt, trösten Sie nicht sofort. Fragen Sie: „Welche Etage hat nachgegeben?“","need":{"3-5":"Bauklötze oder Plastikbecher","6-8":"20 Dinge aus der Küche: Becher, Schwämme, Schachteln","9-12":"Papier, Klebeband, Maßband"},"steps":{"3-5":["Bauen Sie gemeinsam einen Turm, der höher ist als das Knie Ihres Kindes.","Jetzt das höhere Ziel: bis zur Hüfte. Ihr Kind baut, Sie reichen an.","Fällt er um, schauen Sie gemeinsam, wo er gewackelt hat.","Bauen Sie noch einmal mit breitem Fuß und vergleichen Sie."],"6-8":["Legen Sie die Dinge aus und geben Sie eine Minute zum Anschauen.","Die Aufgabe: ein Turm, der höher ist als der Tisch. Ihr Kind baut.","Umgefallen? Finden Sie die Etage, die nachgegeben hat, und tauschen Sie sie aus.","Messen Sie den fertigen Turm in Handspannen und merken Sie sich den Rekord."],"9-12":["Die Vorgabe: nur Papier und Klebeband, nicht an die Wand gelehnt. Ziel: 1 Meter.","Ihr Kind wählt die Form der Stützen: Röhren, Dreiecke oder Faltungen.","7 Minuten bauen, dann messen.","Notieren Sie den Rekord und eine Idee, wie er beim nächsten Mal zu schlagen ist."]}},{"id":"builder-3","scale":"builder","art":"📦🏠🧸","title":"Ein Haus für ein Spielzeug","task":{"3-5":"Bauen Sie aus einer Schachtel und Kissen ein Haus für das Lieblingsspielzeug. Wo ist die Tür? Wo ist das Bett?","6-8":"Bauen Sie aus einer Schachtel ein Spielzeughaus: mit einer Tür, die aufgeht, und einem Fenster. Das Schneiden übernimmt ein Erwachsener.","9-12":"Ihr Kind entwirft ein Haus aus einer Schachtel: erst eine Zeichnung mit Maßen, dann der Bau. Das Haus braucht zwei Stockwerke und eine Treppe."},"why":"Ihr Kind plant einen Raum: was wo steht und wozu. So entsteht die Gewohnheit, erst zu denken und dann zu bauen.","tip":"Fragen Sie im Namen des Spielzeugs: „Und wo schlafe ich? Wie komme ich hinein?“","need":{"3-5":"ein Karton, Kissen, das Lieblingsspielzeug","6-8":"ein Karton, Filzstifte, Klebeband, Schere (ein Erwachsener schneidet)","9-12":"ein Karton, Lineal, Papier, Klebeband, Schere"},"steps":{"3-5":["Fragen Sie: Was für ein Haus braucht das Spielzeug? Groß oder klein?","Bauen Sie Wände aus Kissen und Karton.","Finden Sie gemeinsam heraus, wo die Tür ist und wo das Bett.","Lassen Sie das Spielzeug einziehen und wünschen Sie ihm gute Nacht."],"6-8":["Ihr Kind zeichnet an, wo Tür und Fenster hinkommen.","Der Erwachsene schneidet entlang der Linien und lässt die Tür an einer Seite fest, damit sie aufgeht.","Ihr Kind richtet das Haus ein: Wände, Teppich, Möbel aus kleinen Schachteln.","Hausführung: Ihr Kind zeigt und erzählt."],"9-12":["Zuerst die Zeichnung: zwei Etagen und eine Treppe, Maße in Zentimetern.","Ihr Kind zeichnet die Teile mit dem Lineal an.","Zusammenbau. Scharfe und feste Stellen schneidet der Erwachsene.","Vergleichen Sie das Haus mit der Zeichnung: Was stimmt, was musste geändert werden?"]}},{"id":"builder-4","scale":"builder","art":"🛝⚽🚗","title":"Kugelbahn","task":{"3-5":"Bauen Sie eine Rampe aus Karton oder einem Buch. Lassen Sie einen Ball hinunterrollen. Was ist schneller: der Ball oder ein Spielzeugauto?","6-8":"Bauen Sie aus Papprollen und Klebeband eine Ballbahn an einer Wand oder Tür. Der Ball soll mindestens 5 Sekunden unterwegs sein.","9-12":"Eine Ballbahn mit drei Kurven und einem Becher als Ziel. Stoppen Sie die Zeit. Aufgabe: die Fahrt langsamer machen, ohne dass der Ball stehen bleibt."},"why":"Ein Versuch zu Neigung und Tempo: Ihr Kind ändert eine Bedingung und sieht sofort das Ergebnis.","tip":"Bitten Sie vor jedem Start um eine Vermutung: „Was glaubst du, was ist schneller?“","need":{"3-5":"ein Stück Pappe oder ein großes Buch, ein Ball, größer als die Faust Ihres Kindes, ein Spielzeugauto","6-8":"Papprollen, Kreppband, eine Murmel oder eine Kugel aus Alufolie","9-12":"Rollen, Pappe, Klebeband, ein Becher, Stoppuhr"},"steps":{"3-5":["Bauen Sie eine Rampe: Legen Sie eine Kante der Pappe auf das Sofa oder einen Bücherstapel.","Lassen Sie den Ball rollen, dann das Auto. Was war schneller unten?","Heben Sie die Kante höher und probieren Sie es noch einmal.","Ihr Kind sucht selbst aus, was als Drittes rollt."],"6-8":["Kleben Sie die erste Rolle schräg an eine Tür oder Wand.","Ihr Kind setzt die nächsten an, sodass die Kugel von einer in die andere rollt.","Nach jedem neuen Teil starten und nachbessern.","Ziel: Die Kugel ist mindestens 5 Sekunden unterwegs. Zählen Sie laut mit."],"9-12":["Die Vorgabe: drei Kurven und das Ziel im Becher.","Ihr Kind baut die Bahn und macht einen Probelauf.","Zeit messen. Neue Aufgabe: die Fahrt langsamer machen, ohne dass die Kugel stehen bleibt.","Notieren Sie die Zeit vorher und nachher und was genau geändert wurde."]}},{"id":"builder-5","scale":"builder","art":"🔧🪛🚪","title":"Reparier mit mir","task":{"3-5":"Lassen Sie Ihr Kind einen großen Deckel zudrehen, einen Reißverschluss zuziehen oder einen Klettverschluss schließen. Ihr Kind macht es allein zu Ende.","6-8":"Suchen Sie zu Hause etwas, das festgezogen oder geklebt werden muss. Ihr Kind macht es, Sie geben nur Tipps.","9-12":"Wählen Sie zusammen eine Kleinigkeit, die zu Hause repariert werden muss. Ihr Kind findet die Ursache, schlägt einen Weg vor und repariert. Sie achten auf die Sicherheit."},"why":"Ihr Kind spürt, dass seine Hände etwas Echtes reparieren können. Das stärkt das Selbstvertrauen.","tip":"Halten Sie die Hände hinter dem Rücken. Helfen Sie mit Worten, nicht mit Handgriffen.","need":{"3-5":"ein Glas mit großem Deckel, eine Jacke mit Reißverschluss, Schuhe mit Klettverschluss","6-8":"etwas, das festgezogen oder geklebt werden muss, Schraubendreher oder Kleber","9-12":"eine kleine Reparatur im Haushalt, das passende Werkzeug"},"steps":{"3-5":["Zeigen Sie einmal langsam, wie der Deckel zugedreht wird.","Ihr Kind dreht ihn allein ganz zu.","Dasselbe mit Reißverschluss und Klettverschluss.","Sagen Sie genau, was geklappt hat: „Du hast ihn ganz allein bis oben zugemacht.“"],"6-8":["Suchen Sie gemeinsam, was zu Hause locker ist oder sich gelöst hat.","Ihr Kind schaut es sich an und sagt, was nicht stimmt.","Ihr Kind repariert, Sie geben nur Hinweise.","Prüfen Sie gemeinsam: Hält es?"],"9-12":["Wählen Sie gemeinsam eine Sache: Eine Schranktür quietscht, ein Griff wackelt.","Ihr Kind findet die Ursache und schlägt eine Lösung vor.","Sie prüfen, ob das sicher ist, und Ihr Kind repariert.","Schauen Sie am nächsten Tag nach, ob die Reparatur hält."]}},{"id":"inventor-1","scale":"inventor","art":"💧🍎⛵","title":"Sinkt es oder schwimmt es?","task":{"3-5":"Eine Schüssel Wasser und 6 große Gegenstände. Fragen Sie vor jedem: Sinkt es oder schwimmt es? Dann ausprobieren. Bleiben Sie am Wasser dabei und leeren Sie die Schüssel danach aus.","6-8":"10 Gegenstände. Ihr Kind schreibt für jeden eine Vermutung auf und prüft sie dann. Wie viele stimmten? Was haben die schwimmenden gemeinsam?","9-12":"Ihr Kind baut aus Alufolie ein Boot, das möglichst viele Münzen trägt. Drei Versuche mit verschiedenen Formen. Welche Form hat gewonnen und warum?"},"why":"Vermutung, Versuch, Schluss: Ihr Kind geht den Weg einer Forscherin oder eines Forschers im Kleinen.","tip":"Wenn die Vermutung nicht stimmt, freuen Sie sich: „Das ist ja überraschend! Warum ist das so?“","need":{"3-5":"eine Schüssel Wasser, 6 große Dinge: Schwamm, Löffel, Plastikdeckel, Apfel, Ball, Holzklotz","6-8":"eine Schüssel Wasser, 10 Dinge, Papier und Bleistift","9-12":"Alufolie, eine Schüssel Wasser, Münzen"},"steps":{"3-5":["Fragen Sie vor jedem Ding: Geht es unter oder schwimmt es?","Ihr Kind legt das Ding selbst ins Wasser.","Sortieren Sie auf zwei Seiten: was schwimmt und was untergeht.","Bleiben Sie die ganze Zeit dabei. Schütten Sie das Wasser gleich danach aus."],"6-8":["Ihr Kind schreibt oder malt für jedes Ding eine Vermutung auf.","Es testet der Reihe nach und setzt ein Plus oder ein Minus.","Zählen Sie, wie viele Vermutungen gestimmt haben.","Fragen Sie: Was haben die Dinge gemeinsam, die schwimmen?"],"9-12":["Die Aufgabe: ein Boot aus Alufolie, das die meisten Münzen trägt.","Drei Versuche mit verschiedenen Formen: flach, mit Rand, lang.","Zählen Sie bei jedem die Münzen, bis es untergeht.","Welche Form hat gewonnen und warum? Die Antwort in einem Satz aufschreiben."]}},{"id":"inventor-2","scale":"inventor","art":"🥛🧂🔍","title":"Was passiert, wenn","task":{"3-5":"Mischen Sie Wasser mit dem, was in der Küche da ist: Salz, Zucker, Mehl, Öl. Was verschwindet und was nicht? Probiert wird dabei nichts.","6-8":"Natron und Essig in einem Glas. Erst die Vermutung, dann der Versuch. Was ändert sich mit der doppelten Menge Natron?","9-12":"Ihr Kind überlegt sich eine eigene Frage „Was passiert, wenn …?“ zu Wasser, Eis oder einem Magneten, schreibt eine Vermutung auf, macht den Versuch und notiert das Ergebnis."},"why":"Ihr Kind lernt, eine Bedingung zu ändern und zu beobachten, was sich ändert. So funktioniert jedes Experiment.","tip":"Stellen Sie Fragen, statt zu erklären: „Und wenn wir mehr nehmen? Und wenn es wärmer ist?“","need":{"3-5":"4 Gläser Wasser, Löffel, Salz, Zucker, Mehl, Speiseöl","6-8":"ein Glas, ein Tablett, Natron, Essig, Löffel","9-12":"Wasser, Eis oder ein Magnet zur Wahl, Papier für Notizen"},"steps":{"3-5":["Ihr Kind gibt in jedes Glas einen Löffel von einer Zutat.","Umrühren und schauen: Was ist verschwunden und was nicht?","Finden Sie das Glas, in dem das Spannendste passiert ist.","Probieren ist nicht nötig. Schütten Sie danach alles gemeinsam weg."],"6-8":["Stellen Sie das Glas auf das Tablett. Ihr Kind vermutet: Was passiert?","Einen Löffel Natron hinein, den Essig gießt der Erwachsene ein.","Wiederholen Sie es mit zwei Löffeln Natron.","Was hat sich geändert? Ihr Kind erklärt es mit eigenen Worten."],"9-12":["Ihr Kind denkt sich eine eigene Frage aus: „Was passiert, wenn …?“","Es schreibt eine Vermutung auf.","Es führt den Versuch durch. Sie achten auf die Sicherheit.","Es schreibt das Ergebnis auf und vergleicht es mit der Vermutung."]}},{"id":"inventor-3","scale":"inventor","art":"📦💡♻️","title":"Ein neuer Job für ein altes Ding","task":{"3-5":"Nehmen Sie eine leere Schachtel. Was könnte sie sein? Denken Sie sich drei Ideen aus und spielen Sie jede.","6-8":"Eine Wäscheklammer. Finden Sie 10 Verwendungen, außer Wäsche aufzuhängen. Die beste probieren Sie wirklich aus.","9-12":"Wählen Sie etwas, das weggeworfen werden sollte. Ihr Kind erfindet daraus einen nützlichen Gegenstand für zu Hause und baut ihn."},"why":"Die Gewohnheit, in einem gewöhnlichen Ding viele Möglichkeiten zu sehen. Damit beginnt Erfindergeist.","tip":"Nehmen Sie jede Idee an, auch die seltsamen. Aussortiert wird später.","need":{"3-5":"ein leerer Karton","6-8":"eine Wäscheklammer, ein Blatt Papier","9-12":"etwas, das weggeworfen werden sollte, Kleber, Klebeband, Schere"},"steps":{"3-5":["Fragen Sie: Was könnte dieser Karton sein?","Denken Sie sich drei Dinge aus: ein Auto, ein Haus, ein Hut.","Spielen Sie jedes eine Minute lang.","Welche Idee hat am besten gefallen?"],"6-8":["Die Aufgabe: 10 Arten, eine Wäscheklammer zu benutzen, außer zum Wäscheaufhängen.","Ihr Kind nennt sie, Sie schreiben mit. Die ersten Ideen sind einfach, danach wird es spannender.","Wählen Sie gemeinsam die beste aus.","Probieren Sie sie wirklich aus."],"9-12":["Wählen Sie ein Ding: ein Glas, eine Schachtel, ein altes T-Shirt.","Ihr Kind überlegt, welcher nützliche Gegenstand für zu Hause daraus wird.","Es baut ihn. Sie helfen nur dort, wo Werkzeug nötig ist.","Finden Sie einen Platz dafür und benutzen Sie ihn eine Woche lang."]}},{"id":"inventor-4","scale":"inventor","art":"🥄🍴🔢","title":"Finde das Muster","task":{"3-5":"Legen Sie eine Reihe: Löffel, Gabel, Löffel, Gabel. Was kommt als Nächstes? Dann denkt sich Ihr Kind eine Reihe aus.","6-8":"Schreiben Sie eine Zahlenreihe auf: 2, 4, 6, 8. Wie geht es weiter? Dann 1, 2, 4, 7, 11. Danach stellt Ihr Kind Ihnen eine Reihe.","9-12":"Ihr Kind erfindet eine Geheimschrift (Buchstabe = Zahl oder Zeichen) und schreibt Ihnen eine Nachricht. Ihre Aufgabe: sie entschlüsseln. Dann tauschen Sie."},"why":"In einer Reihe die Regel zu erkennen, braucht man in Mathematik, Musik und beim Programmieren.","tip":"Wenn Ihr Kind Ihnen eine Reihe aufgibt, machen Sie einmal absichtlich einen Fehler. Lassen Sie sich die Regel erklären.","need":{"3-5":"4 Löffel und 4 Gabeln (oder Bauklötze in zwei Farben)","6-8":"ein Blatt Papier, Bleistift","9-12":"Papier, Stift"},"steps":{"3-5":["Legen Sie eine Reihe: Löffel, Gabel, Löffel, Gabel.","Fragen Sie: Was kommt als Nächstes? Ihr Kind legt das nächste Teil.","Machen Sie es schwerer: zwei Löffel, eine Gabel.","Jetzt denkt sich Ihr Kind die Reihe aus und Sie setzen sie fort."],"6-8":["Schreiben Sie eine Reihe: 2, 4, 6, 8. Was kommt danach?","Dann eine schwerere: 1, 2, 4, 7, 11.","Lassen Sie sich die Regel in Worten erklären.","Ihr Kind gibt Ihnen eine eigene Reihe auf."],"9-12":["Ihr Kind erfindet eine Geheimschrift: Jeder Buchstabe ist eine Zahl oder ein Zeichen.","Es schreibt Ihnen eine Nachricht mit einem Satz.","Sie entschlüsseln. Den Schlüssel gibt es erst nach drei Versuchen.","Tauschen Sie die Rollen."]}},{"id":"inventor-5","scale":"inventor","art":"⚙️🔗🔔","title":"Eine Maschine für eine einfache Aufgabe","task":{"3-5":"Wie holt man ein Spielzeug vom Regal, ohne aufzustehen? Probieren Sie eine Schnur, einen Löffel, einen Stock. Was hat funktioniert?","6-8":"Ihr Kind erfindet und zeichnet eine Maschine, die die Katze füttert oder eine Pflanze gießt, und beschriftet, was jedes Teil macht.","9-12":"Bauen Sie eine Kettenreaktion mit 4 Schritten: Dominosteine stoßen einen Ball an, der Ball fällt in einen Becher und so weiter. Ziel: Am Ende klingelt eine Glocke oder ein Löffel fällt."},"why":"Ihr Kind zerlegt eine Aufgabe in Schritte und verbindet sie zu einer Kette. Das ist technisches und logisches Denken zugleich.","tip":"Reparieren Sie die Konstruktion nicht selbst. Fragen Sie: „Bei welchem Schritt ist es stehen geblieben?“","need":{"3-5":"ein Spielzeug auf einem niedrigen Regal, eine Schnur, ein großer Löffel, ein Stock","6-8":"ein Blatt Papier, Stifte","9-12":"Dominosteine, eine Murmel, ein Becher, Bücher, ein Löffel oder ein Glöckchen"},"steps":{"3-5":["Die Aufgabe: das Spielzeug holen, ohne vom Boden aufzustehen.","Probieren Sie nacheinander Schnur, Löffel und Stock.","Was hat am besten funktioniert?","Denken Sie sich gemeinsam noch eine Möglichkeit aus."],"6-8":["Die Aufgabe: eine Maschine erfinden, die die Katze füttert oder eine Blume gießt.","Ihr Kind zeichnet sie vollständig.","Es beschriftet, was jedes Teil tut.","Es erzählt Ihnen von Anfang bis Ende, wie sie funktioniert."],"9-12":["Die Aufgabe: eine Kettenreaktion mit 4 Schritten, am Ende klingelt ein Glöckchen oder fällt ein Löffel.","Ihr Kind baut und testet jeden Schritt einzeln.","Der ganze Durchlauf. Hat es nicht geklappt? Finden Sie den Schritt, an dem es stehen blieb.","Filmen Sie einen gelungenen Durchlauf mit dem Handy."]}},{"id":"storyteller-1","scale":"storyteller","art":"🧸📖✨","title":"Geschichte aus drei Dingen","task":{"3-5":"Nehmen Sie drei Spielsachen. Beginnen Sie mit „Es war einmal …“. Ihr Kind sagt, wie es weitergeht.","6-8":"Drei zufällige Gegenstände aus dem Zimmer. Ihr Kind erfindet eine Geschichte, in der alle drei wichtig sind. Sie hat einen Anfang, ein Problem und ein Ende.","9-12":"Drei zufällige Wörter aus einem Buch. Ihr Kind schreibt in 10 Minuten eine halbe Seite mit einem überraschenden Ende und liest sie vor."},"why":"Ihr Kind baut eine Handlung: Anfang, Schwierigkeit, Auflösung. Das ist die Grundlage für zusammenhängendes Sprechen und Schreiben.","tip":"Korrigieren Sie die Handlung nicht. Helfen Sie mit einer Frage: „Und was ist dann passiert?“","need":{"3-5":"drei Spielsachen","6-8":"drei zufällige Dinge aus dem Zimmer","9-12":"ein Buch, ein Blatt Papier, Stift, Timer"},"steps":{"3-5":["Stellen Sie drei Spielsachen vor Ihr Kind.","Beginnen Sie: „Es war einmal …“ und nennen Sie das erste Spielzeug.","Ihr Kind sagt, wie es weitergeht. Fügen Sie abwechselnd je einen Satz hinzu.","Beenden Sie die Geschichte gemeinsam: Wie ging alles aus?"],"6-8":["Ihr Kind wählt mit geschlossenen Augen drei Dinge.","Die Regel: Alle drei sind in der Geschichte wichtig.","Die Geschichte hat einen Anfang, ein Problem und ein Ende. Ihr Kind erzählt laut.","Erzählen Sie die Geschichte in zwei Sätzen nach: Haben Sie sie richtig verstanden?"],"9-12":["Schlagen Sie das Buch dreimal zufällig auf und schreiben Sie je ein Wort heraus.","In 10 Minuten schreibt Ihr Kind eine halbe Seite Geschichte mit diesen Wörtern.","Die Regel: ein überraschendes Ende.","Ihr Kind liest vor. Sagen Sie, an welcher Stelle es für Sie spannend wurde."]}},{"id":"storyteller-2","scale":"storyteller","art":"📚🐺🔀","title":"Ein anderes Ende","task":{"3-5":"Lesen Sie ein bekanntes Märchen vor und halten Sie vor dem Ende an. Fragen Sie: Wie könnte es noch ausgehen?","6-8":"Ihr Kind erzählt ein Lieblingsmärchen nach, aber der Bösewicht ist diesmal freundlich. Was ändert sich?","9-12":"Ihr Kind erzählt eine bekannte Geschichte aus der Sicht einer Nebenfigur. Was hat diese Figur gesehen, und was wusste sie nicht?"},"why":"Wer eine bekannte Handlung ändert, muss verstehen, wie sie gebaut ist. So wächst flexibles Denken.","tip":"Fragen Sie „Warum hat er das getan?“ und nicht „War das richtig?“.","need":{"3-5":"ein bekanntes Märchenbuch","6-8":"nichts nötig","9-12":"nichts nötig"},"steps":{"3-5":["Lesen Sie das Märchen vor und halten Sie kurz vor dem Ende an.","Fragen Sie: Wie könnte es noch ausgehen?","Nehmen Sie jede Antwort an und führen Sie sie mit einem Satz weiter.","Lesen Sie das echte Ende. Welches gefällt besser?"],"6-8":["Ihr Kind wählt ein Lieblingsmärchen.","Die Regel: Der Bösewicht ist in Wahrheit gut.","Ihr Kind erzählt das Märchen mit dieser Änderung nach.","Sprechen Sie darüber: Was hat sich für die anderen Figuren geändert?"],"9-12":["Wählen Sie eine bekannte Geschichte, ein Buch oder einen Film.","Ihr Kind wählt eine Nebenfigur.","Es erzählt das Geschehen aus ihrer Sicht: was sie gesehen hat und was sie nicht wusste.","Fragen Sie: Wer ist in dieser Fassung die Hauptfigur?"]}},{"id":"storyteller-3","scale":"storyteller","art":"🎤👵❓","title":"Das Interview","task":{"3-5":"Mit einem „Mikrofon“ (einem Löffel) fragt Ihr Kind Sie: Was hast du gern gemocht, als du klein warst?","6-8":"Ihr Kind bereitet 5 Fragen an die Großeltern oder an Sie über die Kindheit vor und führt das Interview. Danach erzählt es, was überrascht hat.","9-12":"Ihr Kind befragt einen Erwachsenen zu seinem Beruf: 7 Fragen, keine mit Ja oder Nein zu beantworten. Dann fasst es das Wichtigste in einer Minute zusammen."},"why":"Ihr Kind lernt, Fragen zu stellen und der Antwort zuzuhören. Das ist die Hälfte jedes guten Gesprächs.","tip":"Antworten Sie ernsthaft und kurz. Das Interview führt Ihr Kind, nicht Sie.","need":{"3-5":"ein großer Löffel als Mikrofon","6-8":"ein Blatt Papier, Bleistift; Oma, Opa oder Sie","9-12":"Notizblock, Stift, ein Erwachsener mit einem spannenden Beruf"},"steps":{"3-5":["Geben Sie Ihrem Kind das „Mikrofon“.","Es fragt: Was hast du gern gemacht, als du klein warst?","Antworten Sie mit einer kurzen Geschichte.","Tauschen Sie: Jetzt stellen Sie die Frage."],"6-8":["Ihr Kind bereitet 5 Fragen zur Kindheit vor.","Es führt das Interview persönlich oder am Telefon.","Das Wichtigste darf es malen oder aufschreiben.","Danach erzählt es Ihnen, was am meisten überrascht hat."],"9-12":["Ihr Kind bereitet 7 Fragen zum Beruf vor. Die Regel: Keine lässt sich mit „Ja“ oder „Nein“ beantworten.","Es führt das Interview und macht Notizen.","In einer Minute fasst es für Sie das Wichtigste zusammen.","Fragen Sie: Welche Frage war die beste?"]}},{"id":"storyteller-4","scale":"storyteller","art":"🔤😄💬","title":"Neue Wörter","task":{"3-5":"Denken Sie sich zusammen für jedes Spielzeug einen lustigen Namen aus und erklären Sie, warum es so heißt.","6-8":"Erfinden Sie ein Wort, das es nicht gibt, und legen Sie fest, was es bedeutet. Benutzen Sie es heute dreimal im Gespräch.","9-12":"Wählen Sie in einem Buch drei unbekannte Wörter. Ihr Kind errät die Bedeutung zuerst aus dem Text, prüft sie dann und bildet mit jedem einen Satz."},"why":"Das Spiel mit Wörtern erweitert den Wortschatz und zeigt, dass man Sprache erfinden kann, nicht nur lernen.","tip":"Benutzen Sie das neue Wort selbst. Ihr Kind sollte es aus Ihrem Mund hören.","need":{"3-5":"3–4 Spielsachen","6-8":"nichts nötig","9-12":"ein Buch, ein Blatt Papier"},"steps":{"3-5":["Nehmen Sie das erste Spielzeug und geben Sie ihm einen lustigen Namen.","Ihr Kind erklärt, warum es so heißt.","Dem nächsten Spielzeug gibt Ihr Kind den Namen.","Stellen Sie die Spielsachen einander mit den neuen Namen vor."],"6-8":["Erfinden Sie gemeinsam ein Wort, das es nicht gibt.","Einigen Sie sich, was es bedeutet.","Aufgabe für heute: es dreimal im Gespräch benutzen.","Zählen Sie abends, wer wie oft daran gedacht hat."],"9-12":["Ihr Kind sucht im Buch drei unbekannte Wörter.","Zuerst rät es die Bedeutung aus den Sätzen drumherum.","Es prüft im Wörterbuch oder fragt Sie.","Mit jedem Wort bildet es einen eigenen Satz."]}},{"id":"storyteller-5","scale":"storyteller","art":"📺🎙️🪟","title":"Live-Reportage","task":{"3-5":"Ihr Kind erzählt wie im Fernsehen, was es aus dem Fenster sieht: „Da kommt ein rotes Auto …“","6-8":"Ihr Kind berichtet eine Minute lang vom Abendessen oder vom Spaziergang: wer, was, wo. Nehmen Sie es mit dem Handy auf und hören Sie es zusammen an.","9-12":"Ihr Kind bereitet eine zweiminütige Nachrichtensendung der Familie für diese Woche vor: drei Meldungen und eine Vorhersage fürs Wochenende. Aufnehmen und der Familie zeigen."},"why":"Ihr Kind beschreibt, was es sieht, der Reihe nach und verständlich für Zuhörer. Das ist die Grundlage fürs Vortragen.","tip":"Seien Sie Publikum: Hören Sie bis zum Ende zu und stellen Sie eine Frage „aus dem Studio“.","need":{"3-5":"ein Fenster","6-8":"ein Handy für die Aufnahme (wenn Sie möchten)","9-12":"ein Blatt Papier, ein Handy für die Aufnahme"},"steps":{"3-5":["Setzen Sie sich gemeinsam ans Fenster.","Machen Sie es mit Sprecherstimme vor: „Da kommt ein rotes Auto …“","Jetzt berichtet Ihr Kind, eine Minute lang.","Bedanken Sie sich bei der „Reporterin“ oder dem „Reporter“ und fragen Sie, was am spannendsten war."],"6-8":["Thema: das Abendessen oder ein Spaziergang.","Ihr Kind berichtet eine Minute lang: wer, was, wo.","Nehmen Sie es mit dem Handy auf.","Hören Sie es gemeinsam an. Was würde es beim nächsten Mal ergänzen?"],"9-12":["Ihr Kind wählt drei Familiennachrichten der Woche.","Es ergänzt eine Vorhersage fürs Wochenende.","Es nimmt eine Sendung von zwei Minuten auf.","Zeigen Sie die Aufnahme der Familie."]}},{"id":"artist-1","scale":"artist","art":"✏️🌀🐾","title":"Bild aus einer Kritzelei","task":{"3-5":"Zeichnen Sie eine Kritzelei. Ihr Kind macht daraus ein Tier: mit Augen, Pfoten, Schwanz.","6-8":"Beide zeichnen eine Kritzelei und tauschen. Aufgabe: aus der fremden Kritzelei ein Bild machen und ihm einen Titel geben.","9-12":"Fünf zufällige Linien auf einem Blatt. Ihr Kind macht daraus eine fertige Zeichnung, in der keine Linie übrig bleibt."},"why":"Ihr Kind lernt, in einer zufälligen Form ein Bild zu sehen. So arbeitet die Fantasie in Kunst und Design.","tip":"Fragen Sie „Was hast du hier gesehen?“ und nicht „Was ist das?“.","need":{"3-5":"ein Blatt Papier, dicke Filzstifte oder Wachsmalstifte","6-8":"zwei Blätter, Filzstifte","9-12":"ein Blatt Papier, Bleistift oder Kugelschreiber"},"steps":{"3-5":["Malen Sie ein Gekritzel auf das Blatt.","Fragen Sie: Wem sieht es ähnlich?","Ihr Kind malt Augen, Pfoten und einen Schwanz dazu.","Geben Sie dem Tier einen Namen."],"6-8":["Jeder malt ein Gekritzel auf sein Blatt.","Tauschen Sie die Blätter.","Die Aufgabe: aus dem fremden Gekritzel ein Bild machen.","Geben Sie den Bildern Titel und zeigen Sie sie einander."],"9-12":["Zeichnen Sie fünf zufällige Linien auf das Blatt.","Ihr Kind macht daraus eine fertige Zeichnung.","Die Regel: Keine Linie bleibt übrig.","Lassen Sie sich zeigen, was aus jeder Linie geworden ist."]}},{"id":"artist-2","scale":"artist","art":"🎨🔵🖌️","title":"Eine Farbe","task":{"3-5":"Nennen Sie eine Farbe. Sammeln Sie in der Wohnung alles in dieser Farbe und legen Sie daraus ein Bild auf den Boden.","6-8":"Malen Sie ein Bild nur mit einer Farbe und ihren Tönen. Wie zeigt man die Nacht, wenn man nur Blau hat?","9-12":"Ihr Kind fotografiert mit dem Handy 7 Gegenstände in einer Farbe so, dass die Bilder wie eine Serie wirken, wählt das beste Foto und erklärt, warum."},"why":"Die Beschränkung auf eine Farbe zwingt dazu, Töne und Formen zu suchen. Das schult das Auge.","tip":"Machen Sie auf die Farbtöne aufmerksam: „Schau, dieses Blau ist dunkler. Wo passt es hin?“","need":{"3-5":"Dinge in einer Farbe aus der Wohnung","6-8":"ein Blatt Papier, Farben oder Stifte in einer Farbe, Wasser","9-12":"ein Handy mit Kamera"},"steps":{"3-5":["Nennen Sie die Farbe des Tages.","Sammeln Sie in der Wohnung alles in dieser Farbe: Spielsachen, Socken, Deckel.","Legen Sie aus den Funden ein Bild auf den Boden.","Fotografieren Sie es und räumen Sie gemeinsam alles zurück."],"6-8":["Ihr Kind wählt eine Farbe.","Die Aufgabe: ein Bild nur mit dieser Farbe und ihren Tönen malen.","Fragen Sie: Wie zeigt man Nacht, wenn es nur Blau gibt?","Suchen Sie im Bild die hellste und die dunkelste Stelle."],"9-12":["Ihr Kind wählt eine Farbe.","Es fotografiert 7 Dinge in dieser Farbe so, dass die Bilder wie eine Serie wirken.","Es wählt das beste Bild aus.","Es erklärt, warum gerade dieses."]}},{"id":"artist-3","scale":"artist","art":"🎵🖍️🌈","title":"Musik auf Papier","task":{"3-5":"Spielen Sie ein schnelles Lied, dann ein langsames. Ihr Kind malt zu jedem. Worin unterscheiden sich die Bilder?","6-8":"Spielen Sie Musik ohne Text. Ihr Kind malt, was es hört: Linien, Flecken, Farben. Dann zeigt es, wo das Bild laut ist.","9-12":"Zwei verschiedene Stücke, zwei Blätter. Ihr Kind zeigt die Stimmung nur mit Form und Farbe, ohne Gegenstände. Sie raten, welches Bild zu welchem Stück gehört."},"why":"Ihr Kind übersetzt Klang in Linie und Farbe. Das verbindet Gehör, Gefühl und Hand.","tip":"Verlangen Sie keine Gegenstände. Hier zählen Linien, Flecken und Stimmung.","need":{"3-5":"zwei Blatt Papier, Wachsmalstifte, zwei Lieder: ein schnelles und ein langsames","6-8":"ein Blatt Papier, Farben oder Filzstifte, Musik ohne Text","9-12":"zwei Blätter, Farben oder Stifte, zwei verschiedene Musikstücke"},"steps":{"3-5":["Spielen Sie das schnelle Lied. Ihr Kind malt dazu auf das erste Blatt.","Spielen Sie das langsame. Zweites Blatt.","Legen Sie die Bilder nebeneinander.","Worin unterscheiden sie sich? Mit dem Finger zeigen."],"6-8":["Spielen Sie Musik ohne Text.","Ihr Kind malt, was es hört: Linien, Flecken, Farben.","Fragen Sie nach der Musik: Wo ist es im Bild laut und wo leise?","Geben Sie dem Bild einen Titel."],"9-12":["Ihr Kind hört das erste Stück und zeigt die Stimmung nur mit Form und Farbe, ohne Gegenstände.","Dasselbe mit dem zweiten Stück.","Sie raten, welches Blatt zu welchem Stück gehört.","Ihr Kind erklärt seine Farbwahl."]}},{"id":"artist-4","scale":"artist","art":"🍂🌰🖼️","title":"Bild aus Fundstücken","task":{"3-5":"Sammeln Sie beim Spaziergang Blätter, Stöckchen und Zapfen. Legen Sie zu Hause daraus ein Gesicht oder ein Tier.","6-8":"Eine Collage aus einer alten Zeitschrift und Fundstücken vom Spaziergang. Thema: „Ein Ort, an dem ich gern wäre“.","9-12":"Ihr Kind ordnet Gegenstände auf dem Tisch wie ein Stillleben an. Bewegen Sie eine Lampe: Wie verändert das Licht das Bild? Die beste Version fotografieren."},"why":"Eine Komposition aus fertigen Dingen lehrt, Form und Oberfläche zu sehen und wie Dinge zusammenpassen.","tip":"Fragen Sie: „Was passiert, wenn wir das hierhin schieben?“ und lassen Sie es ausprobieren.","need":{"3-5":"Blätter, Stöckchen, Zapfen vom Spaziergang, ein Blatt Papier","6-8":"eine alte Zeitschrift, Funde vom Spaziergang, Kleber, ein Blatt Papier, Schere","9-12":"3–5 Gegenstände, eine Tischlampe, ein Handy"},"steps":{"3-5":["Sammeln Sie beim Spaziergang Blätter, Stöckchen und Zapfen.","Breiten Sie die Funde zu Hause auf dem Tisch aus.","Legen Sie gemeinsam ein Gesicht oder ein Tier.","Machen Sie ein Foto. Nach dem Spielen Hände waschen."],"6-8":["Thema: ein Ort, an dem ich gern wäre.","Ihr Kind schneidet oder reißt Bilder aus der Zeitschrift.","Erst auf dem Blatt auslegen, dann kleben.","Es erzählt Ihnen, was das für ein Ort ist."],"9-12":["Ihr Kind stellt Gegenstände auf dem Tisch wie ein Stillleben zusammen.","Es bewegt die Lampe: von der Seite, von oben, von hinten.","Es beobachtet, wie sich Schatten und Stimmung ändern.","Es fotografiert die beste Variante."]}},{"id":"artist-5","scale":"artist","art":"🥔🟣💌","title":"Mein eigenes Muster","task":{"3-5":"Drucken Sie mit Farbe: mit den Fingern, einem Schwamm oder einer halben Kartoffel. So entsteht ein Muster für eine Karte.","6-8":"Ihr Kind entwirft ein Muster für das eigene T-Shirt oder die eigene Tasse und zeichnet es in Originalgröße auf Papier.","9-12":"Ihr Kind entwirft ein Logo für die Familie: drei Skizzen, eine endgültige Fassung. Dann erklärt es, was jedes Detail bedeutet."},"why":"Ein wiederkehrendes Muster lehrt Rhythmus und Sorgfalt, ein Zeichen lehrt, eine Idee knapp auszudrücken.","tip":"Hängen Sie das fertige Werk gut sichtbar auf. Für Ihr Kind bedeutet das mehr als Worte.","need":{"3-5":"Fingerfarbe, ein Schwamm, eine halbe Kartoffel, ein Blatt Papier, eine Wachstuchdecke","6-8":"ein Blatt Papier, Filzstifte","9-12":"Papier, Bleistift, Filzstifte"},"steps":{"3-5":["Decken Sie den Tisch ab.","Zeigen Sie einen Abdruck mit Finger, Schwamm und Kartoffel.","Ihr Kind druckt ein Muster über das ganze Blatt.","Wenn es trocken ist, falten Sie das Blatt in der Mitte: Das ist eine Karte."],"6-8":["Ihr Kind wählt: ein Muster für ein T-Shirt oder für eine Tasse.","Es zeichnet den Umriss in Originalgröße auf das Blatt.","Es füllt ihn mit einem Muster.","Fragen Sie: Wem würde es so etwas schenken?"],"9-12":["Die Aufgabe: ein Zeichen für Ihre Familie.","Drei schnelle Skizzen, je eine Minute.","Ihr Kind wählt eine aus und zeichnet die endgültige Fassung.","Es erklärt, was jedes Detail bedeutet."]}},{"id":"explorer-1","scale":"explorer","art":"🔎🍃🪣","title":"Schatzsuche","task":{"3-5":"Suchen Sie beim Spaziergang: etwas Rundes, etwas Weiches, etwas Gelbes, etwas Lautes.","6-8":"Eine Liste mit 8 Fundstücken für den Spaziergang: ein Blatt mit gezacktem Rand, eine Spur, etwas, das älter ist als Sie, etwas, das gestern noch nicht da war.","9-12":"Ihr Kind schreibt Ihnen eine Liste mit 10 Fundstücken und führt den Weg an. Unterwegs fotografiert es das Seltsamste, das ihm auffällt."},"why":"Die Suche nach einem Merkmal schult die Aufmerksamkeit und den Blick für Details ringsum.","tip":"Zeigen Sie den Fund nicht selbst. Grenzen Sie ein: „Schau weiter unten. Wärmer!“","need":{"3-5":"ein Spaziergang, eine Tüte oder ein Eimerchen","6-8":"eine Liste mit 8 Funden auf einem Zettel, Bleistift","9-12":"ein Zettel, Stift, ein Handy mit Kamera"},"steps":{"3-5":["Nennen Sie vier Aufgaben: etwas Rundes, etwas Weiches, etwas Gelbes, etwas, das Geräusche macht.","Suchen Sie eins nach dem anderen. Ihr Kind zeigt den Fund.","Fragen Sie bei jedem: Wie fühlt es sich an?","Erinnern Sie sich zu Hause an alle vier Funde."],"6-8":["Schreiben Sie die Liste: ein Blatt mit Zacken, eine Spur, etwas, das älter ist als Sie, etwas, das gestern noch nicht da war, und vier eigene.","Beim Spaziergang sucht Ihr Kind und streicht ab.","Bei strittigen Funden soll es begründen, warum es passt.","Welcher Fund war am schwersten?"],"9-12":["Ihr Kind schreibt selbst eine Liste mit 10 Funden für Sie.","Es führt den Weg an, Sie suchen.","Unterwegs fotografiert es das Seltsamste, das ihm auffällt.","Schauen Sie zu Hause die Fotos an und wählen Sie den Fund des Tages."]}},{"id":"explorer-2","scale":"explorer","art":"🗺️❌🧸","title":"Karte vom Zimmer","task":{"3-5":"Verstecken Sie ein Spielzeug und geben Sie Hinweise: „neben dem Bett“, „unter dem Tisch“. Dann versteckt Ihr Kind.","6-8":"Ihr Kind zeichnet eine Karte des Zimmers von oben und markiert den versteckten Schatz mit einem Kreuz. Sie suchen mit der Karte.","9-12":"Ihr Kind zeichnet aus dem Gedächtnis eine Karte des Wegs von zu Hause zur Schule oder zu einem Geschäft. Dann gehen Sie den Weg ab und verbessern die Karte."},"why":"Eine Karte lehrt, sich einen Raum von oben vorzustellen und aufs Papier zu bringen.","tip":"Suchen Sie ehrlich nach der Karte. Ist sie ungenau, soll Ihr Kind selbst sehen, wo es hakt.","need":{"3-5":"das Lieblingsspielzeug","6-8":"ein Blatt Papier, Bleistift, ein kleiner „Schatz“","9-12":"ein Blatt Papier, Bleistift"},"steps":{"3-5":["Verstecken Sie das Spielzeug im Zimmer, während Ihr Kind nicht hinsieht.","Geben Sie Hinweise mit Worten: „neben dem Bett“, „unter dem Tisch“.","Gefunden? Jetzt versteckt es und gibt Ihnen die Hinweise.","Spielen Sie drei Runden."],"6-8":["Ihr Kind zeichnet das Zimmer von oben: Bett, Tisch, Tür.","Es versteckt den Schatz und setzt ein Kreuz auf die Karte.","Sie suchen nur nach der Karte.","Tauschen Sie: Die Karte zeichnen Sie."],"9-12":["Ihr Kind zeichnet aus dem Gedächtnis den Weg von zu Hause zur Schule oder zum Laden.","Es markiert die Abzweigungen und drei Orientierungspunkte.","Gehen Sie den Weg gemeinsam mit der Karte in der Hand ab.","Korrigieren Sie auf der Karte, was nicht gestimmt hat."]}},{"id":"explorer-3","scale":"explorer","art":"🤫👂🐦","title":"Fünf stille Minuten","task":{"3-5":"Setzen Sie sich 2 Minuten ans Fenster. Was hören Sie? Zählen Sie die Geräusche an den Fingern.","6-8":"5 Minuten draußen ohne zu sprechen. Danach nennt jeder drei Dinge, die er bemerkt hat und der andere nicht.","9-12":"10 Minuten einen Ort beobachten (ein Vogelhäuschen, eine Kreuzung, einen Ameisenhaufen). Ihr Kind notiert, was passiert, und findet ein Muster."},"why":"Stilles Beobachten lehrt, zu bemerken, was man sonst übersieht. Es ist das wichtigste Werkzeug beim Entdecken.","tip":"Schweigen Sie mit Ihrem Kind. Ihr Vorbild wirkt besser als „Sitz still“.","need":{"3-5":"ein Fenster oder eine Bank","6-8":"Hof oder Park, Timer auf 5 Minuten","9-12":"Notizblock, Stift, ein Beobachtungsort: Futterhäuschen, Kreuzung, Ameisenhaufen"},"steps":{"3-5":["Setzen Sie sich 2 Minuten nebeneinander.","Schließen Sie die Augen und lauschen Sie.","Zählen Sie jedes neue Geräusch an den Fingern ab.","Welches Geräusch war das leiseste?"],"6-8":["Vereinbaren Sie: 5 Minuten schweigen und schauen.","Jeder merkt sich, was ihm auffällt.","Dann nennt abwechselnd jeder drei Dinge.","Es gewinnt, wer etwas bemerkt hat, das der andere nicht gesehen hat."],"9-12":["Ihr Kind wählt einen Ort und beobachtet 10 Minuten.","Es schreibt auf, was passiert und wann.","Es sucht eine Regelmäßigkeit: Was wiederholt sich?","Es erzählt Ihnen den Schluss und wie man ihn morgen überprüfen kann."]}},{"id":"explorer-4","scale":"explorer","art":"🧦🔴🗂️","title":"Meine Sammlung","task":{"3-5":"Sortieren Sie große Deckel, Socken oder Bauklötze in Häufchen: nach Farbe, dann nach Größe.","6-8":"Sammeln Sie 10 Blätter oder Steine. Ihr Kind entscheidet, wie sie in Gruppen aufgeteilt werden, und erklärt die Regel.","9-12":"Ihr Kind beginnt eine Sammlung für eine Woche: jeden Tag ein Fundstück mit einem Schildchen, wo und wann es gefunden wurde. Am Ende der Woche gibt es eine kleine Ausstellung."},"why":"Sortieren lehrt, ein Merkmal zu finden und die Regel zu erklären. Damit beginnt jedes Ordnen und Einteilen.","tip":"Geben Sie die Regel nicht vor. Fragen Sie: „Warum gehören diese zusammen?“","need":{"3-5":"große Deckel, Socken oder Bauklötze","6-8":"10 Blätter oder Steine vom Spaziergang","9-12":"eine Schachtel oder ein Regalfach, Zettel zum Beschriften"},"steps":{"3-5":["Schütten Sie die Dinge auf den Boden.","Sortieren Sie gemeinsam nach Farbe.","Mischen Sie und sortieren Sie nach Größe: groß und klein.","Ihr Kind denkt sich eine dritte Art aus."],"6-8":["Breiten Sie die Funde auf dem Tisch aus.","Ihr Kind entscheidet selbst, wie es sie in Gruppen teilt.","Es erklärt die Regel.","Bitten Sie es, noch einmal nach einer anderen Regel zu teilen."],"9-12":["Ihr Kind wählt ein Thema für eine Wochensammlung.","Jeden Tag ein Fund mit Zettel: wo und wann gefunden.","Am Ende der Woche macht es daraus eine Ausstellung.","Es führt die Familie zwei Minuten lang herum."]}},{"id":"explorer-5","scale":"explorer","art":"❓📗🔭","title":"Frage des Tages","task":{"3-5":"Ihr Kind stellt eine Warum-Frage. Suchen Sie die Antwort zusammen: in einem Buch, draußen oder mit einem Versuch.","6-8":"Ihr Kind wählt ein Tier und findet drei Fakten darüber, die Sie nicht kannten. Prüfen Sie, ob Sie sie wirklich nicht kannten.","9-12":"Ihr Kind wählt eine Frage ohne schnelle Antwort, findet zwei verschiedene Quellen und erklärt Ihnen, worin sie sich unterscheiden."},"why":"Ihr Kind lernt, eine Antwort selbst zu suchen und zu überprüfen.","tip":"Sagen Sie ehrlich: „Das weiß ich nicht, lass es uns herausfinden.“ Ein besseres Vorbild gibt es nicht.","need":{"3-5":"ein Kinderlexikon oder ein Fenster","6-8":"ein Tierbuch oder gemeinsame Suche mit einem Erwachsenen","9-12":"zwei Quellen: ein Buch und eine Website oder zwei Websites"},"steps":{"3-5":["Ihr Kind stellt eine Warum-Frage.","Sagen Sie: Lass es uns gemeinsam herausfinden.","Suchen Sie die Antwort im Buch, draußen oder mit einem einfachen Versuch.","Bitten Sie Ihr Kind, die Antwort einem anderen Erwachsenen zu erzählen."],"6-8":["Ihr Kind wählt ein Tier.","Es findet drei Fakten darüber, die Sie nicht kannten.","Es erzählt sie Ihnen.","Sagen Sie ehrlich, welche davon Sie wirklich nicht kannten."],"9-12":["Ihr Kind wählt eine Frage, auf die es keine schnelle Antwort gibt.","Es findet zwei verschiedene Quellen.","Es vergleicht: Worin stimmen sie überein und worin nicht?","Es erzählt, welcher es mehr vertraut und warum."]}},{"id":"leader-1","scale":"leader","art":"⏱️👑🎲","title":"15 Minuten das Kommando","task":{"3-5":"15 Minuten lang bestimmt Ihr Kind: Es wählt das Spiel und sagt, wer was macht. Sie machen mit.","6-8":"Ihr Kind plant einen Familienspaziergang von einer Stunde: wohin es geht, was mitkommt, wer wofür zuständig ist.","9-12":"Ihr Kind organisiert einen Familienabend: ein Programm, eine Rolle für jeden, ein Budget, das Sie festlegen. Danach besprechen Sie, wie es gelaufen ist."},"why":"Ihr Kind probiert aus, für andere verantwortlich zu sein: entscheiden, verteilen, sich einigen.","tip":"Folgen Sie ernsthaft. Ist eine Entscheidung ungünstig, soll Ihr Kind das Ergebnis selbst sehen.","need":{"3-5":"Timer auf 15 Minuten","6-8":"ein Blatt Papier, Bleistift","9-12":"ein Blatt Papier, ein Budget, das Sie nennen"},"steps":{"3-5":["Kündigen Sie an: 15 Minuten lang bestimmst du.","Ihr Kind wählt das Spiel.","Es sagt, wer was macht. Sie folgen.","Wenn der Timer klingelt, bedanken Sie sich bei Ihrem „Kapitän“."],"6-8":["Die Aufgabe: einen einstündigen Familienspaziergang planen.","Ihr Kind entscheidet, wohin es geht und was mitkommt.","Es legt fest, wer wofür zuständig ist.","Gehen Sie nach seinem Plan. Was hat funktioniert?"],"9-12":["Ihr Kind organisiert einen Familienabend.","Es stellt ein Programm und Rollen für alle zusammen.","Es bleibt im Budget.","Sprechen Sie danach darüber: Was ist gelungen und was würde es anders machen?"]}},{"id":"leader-2","scale":"leader","art":"⚽📋🎲","title":"Ein neues Spiel","task":{"3-5":"Erfinden Sie ein Ballspiel mit einer Regel. Spielen Sie es. Ihr Kind fügt eine zweite Regel hinzu.","6-8":"Ihr Kind erfindet ein Spiel mit drei Regeln und erklärt es der Familie. Wenn jemand es nicht versteht, braucht die Regel einfachere Worte.","9-12":"Ihr Kind entwirft ein Brettspiel auf einem Blatt Papier: das Ziel, die Züge, wie man gewinnt. Spielen Sie es und verbessern Sie zusammen eine schwache Regel."},"why":"Eine Regel zu erfinden und anderen zu erklären, heißt lernen, ohne Schreien anzuleiten.","tip":"Ist eine Regel unklar, denken Sie nicht für Ihr Kind weiter. Sagen Sie: „Das habe ich nicht verstanden. Erklär es einfacher.“","need":{"3-5":"ein Ball","6-8":"beliebige Spielsachen oder ein Ball","9-12":"ein Blatt Papier, Bleistift, Würfel, Spielfiguren"},"steps":{"3-5":["Denken Sie sich ein Ballspiel mit einer Regel aus. Zum Beispiel: Wir rollen nur im Sitzen.","Spielen Sie zwei Minuten.","Ihr Kind fügt eine zweite Regel hinzu.","Spielen Sie nach den neuen Regeln."],"6-8":["Ihr Kind erfindet ein Spiel mit drei Regeln.","Es erklärt es der Familie.","Jemand hat es nicht verstanden? Dann muss die Regel einfacher gesagt werden.","Spielen Sie eine Runde."],"9-12":["Ihr Kind zeichnet ein Brettspiel: Ziel, Züge, wie man gewinnt.","Spielen Sie eine Partie.","Finden Sie gemeinsam eine schwache Regel.","Verbessern Sie sie und spielen Sie noch einmal."]}},{"id":"leader-3","scale":"leader","art":"🍎🍌💬","title":"Überzeuge mich","task":{"3-5":"Ihr Kind wählt zwischen zwei Dingen (Apfel oder Banane) und sagt, warum. Ein Grund genügt.","6-8":"Ihr Kind möchte zu Hause etwas ändern (Schlafenszeit, Speiseplan). Bitten Sie um drei Gründe. Gute Argumente gewinnen.","9-12":"Eine Debatte mit Regeln: Ihr Kind vertritt 2 Minuten lang eine Meinung, dann 2 Minuten lang das Gegenteil. Welche Seite war stärker?"},"why":"Ihr Kind lernt, sich mit Argumenten durchzusetzen statt mit Hartnäckigkeit.","tip":"Überlegen Sie vorher, worauf Sie sich einlassen würden. Das letzte Wort bleibt bei Ihnen.","need":{"3-5":"zwei Dinge zur Wahl: Apfel und Banane, zwei Bücher","6-8":"nichts nötig","9-12":"Timer"},"steps":{"3-5":["Bieten Sie zwei Dinge zur Wahl an.","Ihr Kind wählt und sagt, warum.","Ein Grund genügt.","Wiederholen Sie sein Argument laut: „Du hast die Banane genommen, weil sie süß ist.“"],"6-8":["Ihr Kind nennt eine Sache, die es zu Hause ändern möchte.","Es nennt drei Gründe.","Sie gehen auf jeden sachlich ein.","Gute Argumente zählen. Die Entscheidung liegt bei Ihnen, und Sie begründen sie."],"9-12":["Wählen Sie ein Streitthema.","Zwei Minuten lang vertritt Ihr Kind seine eigene Meinung.","Zwei Minuten lang vertritt es die Gegenmeinung.","Welche Seite war stärker und warum?"]}},{"id":"leader-4","scale":"leader","art":"🤝🧺⭐","title":"Die rechte Hand","task":{"3-5":"Heute bestimmen Sie, und Ihr Kind hilft: Sie bitten, Ihr Kind erledigt drei Aufgaben. Bedanken Sie sich für jede.","6-8":"Im Spiel führt Ihr Kind heute nicht, sondern hilft einem jüngeren Kind oder Ihnen. Fragen Sie danach: Was war schwierig?","9-12":"Ihr Kind hilft jemandem, dessen Idee zu Ende zu bringen, ohne sie durch die eigene zu ersetzen. Besprechen Sie danach, wo es am liebsten übernommen hätte."},"why":"Wer anführt, muss auch Zweiter sein können: zuhören, helfen und nichts an sich reißen.","tip":"Danken Sie für etwas Konkretes: „Du hast alles auf einmal gebracht, so sind wir fertig geworden.“","need":{"3-5":"drei einfache Aufgaben im Haushalt","6-8":"ein beliebiges Spiel","9-12":"eine fremde Idee: ein Projekt von Bruder, Schwester oder Ihnen"},"steps":{"3-5":["Kündigen Sie an: Heute bestimme ich, und du hilfst mir.","Bitten Sie um die erste Aufgabe.","Bedanken Sie sich und nennen Sie die zweite, dann die dritte.","Sagen Sie, wobei Ihnen die Hilfe genützt hat."],"6-8":["Im Spiel führt Ihr Kind heute nicht an.","Es hilft einem jüngeren Kind oder Ihnen.","Spielen Sie 10 Minuten.","Fragen Sie: Was war schwer? Was hat gefallen?"],"9-12":["Ihr Kind wählt, wem es hilft.","Die Aufgabe: die fremde Idee zu Ende bringen, ohne sie durch die eigene zu ersetzen.","Es arbeitet 10 Minuten.","Sprechen Sie darüber: In welchem Moment wollte es die Sache auf seine Art machen?"]}},{"id":"leader-5","scale":"leader","art":"🪙🛒🍪","title":"Ein kleines Vorhaben","task":{"3-5":"Kaufladen spielen: Ihr Kind verkauft, Sie kaufen ein. Ihr Kind nennt den Preis und zählt die „Münzen“ aus Papier.","6-8":"Ihr Kind entscheidet, was für Nachbarn oder Familie gemacht wird (Karten, Kekse), und verteilt die Aufgaben in der Familie.","9-12":"Ihr Kind plant ein kleines Vorhaben fürs Wochenende: was wir machen, für wen, was es kostet. Dann rechnet es Kosten und Ergebnis zusammen."},"why":"Ein kleines Vorhaben mit Preis und Ergebnis lehrt Rechnen, Planen und an andere zu denken.","tip":"Lassen Sie Ihr Kind selbst rechnen. Einen Rechenfehler suchen Sie gemeinsam.","need":{"3-5":"Spielsachen als „Ware“, „Münzen“ aus Papier","6-8":"Papier und Stifte oder Zutaten für Kekse","9-12":"ein Blatt Papier, Taschenrechner"},"steps":{"3-5":["Schneiden Sie vorher 10 Papiermünzen aus.","Ihr Kind legt die Ware aus: Es führt den Laden.","Sie kaufen ein. Es nennt den Preis und zählt die Münzen.","Tauschen Sie die Rollen."],"6-8":["Ihr Kind entscheidet, was es für Nachbarn oder Verwandte macht.","Es verteilt Aufgaben in der Familie.","Sie machen es gemeinsam nach seinem Plan.","Es überreicht das Ergebnis selbst."],"9-12":["Ihr Kind denkt sich ein kleines Vorhaben fürs Wochenende aus.","Es schreibt auf: was wir machen, für wen, was es kostet.","Es rechnet die Ausgaben zusammen.","Nach dem Wochenende zieht es Bilanz."]}},{"id":"helper-1","scale":"helper","art":"😀😢😮","title":"Wie fühlen sich die anderen?","task":{"3-5":"Zeigen Sie mit dem Gesicht: Freude, Traurigkeit, Wut, Überraschung. Ihr Kind rät und macht es nach.","6-8":"Schlagen Sie in einem Buch ein Bild auf. Wie fühlt sich jede Figur? Woran erkennt man das?","9-12":"Schauen Sie eine Filmminute ohne Ton. Ihr Kind erklärt, wie sich die Figuren fühlen und was vermutlich gesagt wurde."},"why":"Ihr Kind lernt, Gefühle an Gesicht und Haltung abzulesen. Das ist die Grundlage für Mitgefühl.","tip":"Benennen Sie auch Ihre eigenen Gefühle: „Ich bin gerade müde, das sieht man an meinen Schultern.“","need":{"3-5":"ein Spiegel (wenn Sie möchten)","6-8":"ein Bilderbuch","9-12":"eine Minute aus einem Film ohne Ton"},"steps":{"3-5":["Zeigen Sie mit dem Gesicht Freude. Ihr Kind rät.","Dann Traurigkeit, Wut, Überraschung.","Ihr Kind macht jeden Ausdruck nach.","Jetzt zeigt es, und Sie raten."],"6-8":["Schlagen Sie ein Bild mit mehreren Figuren auf.","Was fühlt jede einzelne?","Woran sieht man das: Gesicht, Hände, Haltung?","Was würde die Figur sagen, wenn sie könnte?"],"9-12":["Spielen Sie eine Minute Film ohne Ton ab.","Ihr Kind erklärt, was die Figuren fühlen.","Es sagt, was vermutlich gesprochen wurde.","Spielen Sie die Szene mit Ton ab und vergleichen Sie."]}},{"id":"helper-2","scale":"helper","art":"🎁🤫💛","title":"Die heimliche gute Tat","task":{"3-5":"Bereiten Sie zusammen eine Überraschung für jemanden zu Hause vor: ein Bild unter dem Kopfkissen oder ein gedeckter Tisch.","6-8":"Ihr Kind wählt einen Menschen und tut ihm etwas Gutes, ohne dass dieser weiß, von wem es kommt.","9-12":"Ihr Kind bemerkt, wer in der Familie es gerade schwer hat, und überlegt selbst, wie es helfen kann. Sie besorgen nur, was gebraucht wird."},"why":"Eine gute Tat ohne Belohnung lehrt, sich um andere zu kümmern, nicht um das Lob.","tip":"Bewahren Sie das Geheimnis. Verraten Sie nicht, von wem die Überraschung kam.","need":{"3-5":"Papier, Wachsmalstifte oder Geschirr für den Tisch","6-8":"nichts nötig","9-12":"was für die Hilfe gebraucht wird"},"steps":{"3-5":["Wählen Sie aus, wen zu Hause Sie überraschen.","Entscheiden Sie, womit: ein Bild unter dem Kopfkissen oder ein gedeckter Tisch.","Machen Sie es gemeinsam und leise.","Schauen Sie aus der Ferne zu, wie sich die Person freut."],"6-8":["Ihr Kind wählt eine Person.","Es denkt sich eine gute Tat für sie aus.","Es macht sie so, dass die Person nicht erfährt, von wem sie kam.","Abends erzählt es Ihnen, wie sich das angefühlt hat."],"9-12":["Ihr Kind bemerkt, wer in der Familie es gerade nicht leicht hat.","Es überlegt selbst, wie es helfen kann.","Sie geben nur, was dafür nötig ist.","Fragen Sie danach: Woran hat es gemerkt, dass die Person Hilfe braucht?"]}},{"id":"helper-3","scale":"helper","art":"📕📗☝️","title":"Und was will ich?","task":{"3-5":"Bieten Sie zwei Möglichkeiten an: welches Buch, welche Tasse. Ihr Kind wählt selbst und sagt es laut.","6-8":"Heute sagt Ihr Kind dreimal „Ich möchte …“ und einmal höflich „Nein“. Üben Sie es im Spiel.","9-12":"Besprechen Sie eine Situation, in der Ihr Kind zugestimmt hat, obwohl es nicht wollte. Wie hätte ein freundliches Nein geklungen? Üben Sie den Satz."},"why":"Ein einfühlsames Kind sollte auch die eigenen Wünsche hören können, nicht nur die der anderen.","tip":"Nehmen Sie sein „Nein“ gelassen an. So erfährt es, dass ein Nein die Beziehung nicht zerstört.","need":{"3-5":"zwei Bücher oder zwei Tassen","6-8":"nichts nötig","9-12":"nichts nötig"},"steps":{"3-5":["Bieten Sie zwei Dinge zur Wahl an.","Ihr Kind wählt selbst und sagt laut: „Ich möchte das hier.“","Wiederholen Sie die Wahl dreimal am Tag bei verschiedenen Dingen.","Fragen Sie nicht nach und bieten Sie nichts Drittes an."],"6-8":["Spielen Sie ein Spiel: Sie schlagen vor, Ihr Kind antwortet.","Die Aufgabe: dreimal „Ich möchte …“ sagen.","Und einmal höflich „Nein“ sagen.","Sagen Sie, dass Ihnen gefallen hat, wie es abgelehnt hat."],"9-12":["Erinnern Sie sich an eine Situation, in der Ihr Kind zugestimmt hat, obwohl es nicht wollte.","Sprechen Sie darüber: Was hat das Nein schwer gemacht?","Überlegen Sie einen Satz, der niemanden verletzt.","Üben Sie ihn zweimal laut."]}},{"id":"helper-4","scale":"helper","art":"💌🖍️🙏","title":"Ein Dankesbrief","task":{"3-5":"Ihr Kind malt eine Karte für jemanden, der geholfen hat. Sie schreiben die Worte Ihres Kindes dazu.","6-8":"Ihr Kind schreibt drei Sätze Dank an eine Lehrkraft, eine Trainerin oder einen Trainer oder an Nachbarn: wofür genau und was es verändert hat.","9-12":"Ihr Kind schreibt einen Brief an einen Menschen, dem es lange nicht gedankt hat, und entscheidet selbst, wie der Brief ankommt."},"why":"Dank in Worten lehrt, zu bemerken, was andere für einen tun.","tip":"Helfen Sie, sich an etwas Konkretes zu erinnern: „Wofür genau danke?“","need":{"3-5":"Papier, Wachsmalstifte","6-8":"ein Blatt Papier, Stift","9-12":"Papier, Stift, Umschlag"},"steps":{"3-5":["Fragen Sie: Wer hat dir vor Kurzem geholfen?","Ihr Kind malt dieser Person eine Karte.","Sie schreiben seine Worte dazu, ohne etwas zu ändern.","Überreichen Sie die Karte gemeinsam."],"6-8":["Ihr Kind wählt: eine Lehrkraft, eine Trainerin oder ein Trainer, jemand aus der Nachbarschaft.","Es schreibt drei Sätze: wofür danke und was das verändert hat.","Sie ändern den Text nicht; Fehler korrigieren Sie nur, wenn es darum bittet.","Es übergibt den Zettel selbst."],"9-12":["Ihr Kind denkt an einen Menschen, dem es lange nicht gedankt hat.","Es schreibt ihm einen Brief.","Es entscheidet selbst, wie er ankommt: persönlich, per Post, als Nachricht.","Es übergibt ihn noch diese Woche."]}},{"id":"helper-5","scale":"helper","art":"🧑‍🏫🪥🧥","title":"10 Minuten Unterricht geben","task":{"3-5":"Ihr Kind bringt einem Spielzeug oder Ihnen etwas bei, das es kann: Zähne putzen, die Jacke anziehen.","6-8":"Ihr Kind bringt Ihnen oder einem jüngeren Kind etwas bei, das es gut kann. Sie geben sich Mühe und machen manchmal Fehler.","9-12":"Ihr Kind bereitet für die Familie eine zehnminütige Unterrichtsstunde zu einem Thema vor, in dem es sich auskennt: eine Erklärung, ein Beispiel, eine Kontrollfrage."},"why":"Wer anderen etwas erklärt, versteht es selbst besser und fühlt sich kompetent.","tip":"Seien Sie eine fleißige Schülerin oder ein fleißiger Schüler und machen Sie ab und zu einen Fehler. Lassen Sie sich korrigieren.","need":{"3-5":"ein Spielzeug, eine Zahnbürste oder eine Jacke","6-8":"etwas, das Ihr Kind gut kann","9-12":"ein Blatt Papier für den Plan"},"steps":{"3-5":["Fragen Sie: Was kannst du schon allein?","Ihr Kind bringt es einem Spielzeug oder Ihnen bei: Zähne putzen, Jacke anziehen.","Machen Sie einen Fehler. Lassen Sie sich zeigen, wie es richtig geht.","Bedanken Sie sich für den Unterricht."],"6-8":["Ihr Kind wählt eine Fähigkeit.","Es bringt sie Ihnen oder einem jüngeren Kind Schritt für Schritt bei.","Sie geben sich Mühe und machen einmal einen Fehler.","Zeigen Sie am Ende, was Sie gelernt haben."],"9-12":["Ihr Kind wählt ein Thema, in dem es sich auskennt.","Es bereitet eine 10-minütige Stunde vor: Erklärung, Beispiel, Kontrollfrage.","Es hält sie für die Familie.","Jeder nennt eine Sache, die er gelernt hat."]}},{"id":"mover-1","scale":"mover","art":"🪑🧗🏁","title":"Hindernisparcours","task":{"3-5":"Kissen, ein Stuhl, ein Seil auf dem Boden: darübersteigen, darunter durchkriechen, auf der Linie gehen. Drei Runden.","6-8":"Ihr Kind baut zu Hause einen Parcours mit 5 Hindernissen und läuft ihn auf Zeit. Ist der zweite Versuch schneller?","9-12":"Ihr Kind baut einen Parcours mit 6 Stationen und legt Strafregeln fest. Sie laufen beide auf Zeit, drei Versuche, die Ergebnisse werden notiert."},"why":"Ein Hindernisparcours fördert die Koordination und die Fähigkeit, eine Bewegung zu planen.","tip":"Räumen Sie scharfe Kanten und rutschige Teppiche aus dem Weg. Loben Sie Sorgfalt, nicht nur Tempo.","need":{"3-5":"Kissen, ein Stuhl, ein Seil oder ein Gürtel","6-8":"Kissen, Stühle, ein Seil, Stoppuhr","9-12":"Dinge aus dem Haushalt, Stoppuhr, ein Blatt zum Notieren"},"steps":{"3-5":["Legen Sie das Seil als Linie auf den Boden, daneben Kissen und Stuhl.","Zeigen Sie den Weg: darübersteigen, unter dem Stuhl durchkriechen, auf der Linie gehen.","Ihr Kind läuft drei Runden.","Gehen Sie die letzte Runde gemeinsam."],"6-8":["Ihr Kind baut selbst einen Parcours mit 5 Hindernissen.","Es läuft ihn auf Zeit.","Zweiter Versuch: Geht es schneller?","Fragen Sie, welches Hindernis am schwersten ist."],"9-12":["Ihr Kind baut einen Parcours mit 6 Stationen.","Es legt Strafregeln für Fehler fest.","Sie laufen beide, je drei Versuche.","Notieren Sie die Ergebnisse. Wer hat sich mehr verbessert?"]}},{"id":"mover-2","scale":"mover","art":"🎶🕺🧊","title":"Stopptanz","task":{"3-5":"Musik an, alle tanzen. Musik aus, alle bleiben stehen. Wer bleibt still, bis 5 gezählt ist?","6-8":"Tanzen und auf einem Bein stehen bleiben. In jeder Runde 2 Sekunden länger halten.","9-12":"Stopptanz mit Aufgabe: beim Signal eine Position einnehmen (Stütz, Standwaage, Kniebeuge) und 20 Sekunden halten. Ihr Kind wählt die Positionen für Sie aus."},"why":"Das Stopptanz-Spiel übt, auf ein Signal anzuhalten. Das ist die Grundlage der Selbststeuerung.","tip":"Spielen Sie mit. Ihr Kind soll sehen, dass Stillstehen auch Ihnen schwerfällt.","need":{"3-5":"Musik","6-8":"Musik","9-12":"Musik, Timer"},"steps":{"3-5":["Machen Sie Musik an und tanzen Sie gemeinsam.","Halten Sie die Musik an: Alle erstarren.","Zählen Sie laut bis 5.","Spielen Sie fünf Runden."],"6-8":["Tanzen Sie zur Musik.","Bei Stopp auf einem Bein erstarren.","Jede Runde 2 Sekunden länger stehen.","Bis zu welcher Zahl sind Sie gekommen?"],"9-12":["Bei Stopp eine Position einnehmen: Unterarmstütz, Standwaage oder Kniebeuge.","20 Sekunden halten.","Die Positionen für Sie denkt sich Ihr Kind aus.","Fünf Runden, dann tauschen."]}},{"id":"mover-3","scale":"mover","art":"🤹⚽📈","title":"Ein neuer Trick","task":{"3-5":"Einen weichen Ball hochwerfen und mit beiden Händen fangen. Dann in die Hände klatschen, solange der Ball in der Luft ist.","6-8":"Wählen Sie einen Trick: 10 Seilsprünge am Stück oder einen Luftballon 20-mal in der Luft halten. Fünf Minuten üben, dann zählt es. Platzt der Ballon, sammelt ein Erwachsener die Reste ein.","9-12":"Ihr Kind wählt eine Fertigkeit für die Woche (mit zwei Bällen jonglieren, Handstand an der Wand, Ball hochhalten mit dem Fuß). Heute: der erste Stand und ein Plan."},"why":"Ihr Kind sieht, dass eine Fähigkeit durch Üben wächst. Das verändert seine Haltung zu Schwierigem.","tip":"Zählen Sie Versuche, nicht Fehler: „Das war der zwölfte, er war schon ruhiger.“","need":{"3-5":"ein weicher Ball","6-8":"ein Springseil oder ein Luftballon","9-12":"zwei Bälle oder eine Wand, ein Blatt zum Notieren"},"steps":{"3-5":["Ihr Kind wirft den Ball hoch und fängt ihn mit beiden Händen.","Fünfmal hintereinander.","Machen Sie es schwerer: klatschen, solange der Ball in der Luft ist.","Wie oft hat es geklatscht?"],"6-8":["Wählen Sie einen Trick: 10 Sprünge hintereinander oder den Ballon 20-mal antippen.","Fünf Minuten üben.","Dann die Prüfung: laut mitzählen.","Einen geplatzten Ballon räumt der Erwachsene weg."],"9-12":["Ihr Kind wählt eine Fähigkeit für die Woche: Jonglieren, Handstand an der Wand, Ball hochhalten.","Heute die erste Messung: Wie viel klappt jetzt?","Es macht einen Plan: 5 Minuten am Tag.","Hängen Sie das Blatt mit dem Ergebnis gut sichtbar auf."]}},{"id":"mover-4","scale":"mover","art":"🐻🔤🤸","title":"Buchstaben mit dem Körper","task":{"3-5":"Zeigen Sie mit dem Körper Tiere: wie ein Bär geht, ein Hase hüpft, eine Schlange kriecht. Ihr Kind rät und macht es nach.","6-8":"Ihr Kind formt mit dem Körper die Buchstaben seines Namens, und Sie raten. Dann formen Sie zusammen ein Wort.","9-12":"Einmaleins in Bewegung: Das Ergebnis wird nicht gesagt, sondern gesprungen oder mit dem Ball geprellt. 10 Aufgaben auf Zeit."},"why":"Buchstaben und Zahlen mit dem Körper darzustellen macht das Üben lebendiger.","tip":"Lachen Sie gemeinsam. Je lustiger die Haltung, desto besser bleibt sie im Kopf.","need":{"3-5":"freier Platz","6-8":"freier Platz","9-12":"ein Ball, Timer"},"steps":{"3-5":["Zeigen Sie, wie ein Bär geht.","Ihr Kind rät und macht es nach.","Dann ein Hase und eine Schlange.","Jetzt denkt es sich das Tier aus."],"6-8":["Ihr Kind zeigt mit dem Körper den ersten Buchstaben seines Namens.","Sie raten.","Es zeigt die übrigen Buchstaben.","Zeigen Sie zu zweit ein kurzes Wort."],"9-12":["Sie nennen eine Aufgabe aus dem Einmaleins.","Die Antwort wird gehüpft oder mit dem Ball geprellt.","Zehn Aufgaben auf Tempo.","Tauschen Sie: Die Aufgaben stellt Ihr Kind."]}},{"id":"mover-5","scale":"mover","art":"🏃🧸😌","title":"Eine ruhige Minute nach dem Rennen","task":{"3-5":"Zwei Minuten rennen und springen. Dann auf den Rücken legen, ein Spielzeug auf den Bauch: Wie schaukelt es?","6-8":"5 Minuten aktives Spiel, dann 5 Minuten eine ruhige Beschäftigung (ein Puzzle, ein Bild). Beobachten Sie zusammen: Fällt das Sitzen nach der Bewegung leichter?","9-12":"Ihr Kind macht einen eigenen Test: 10 Minuten lesen nach dem Aufwärmen und 10 Minuten ohne. Wann ist mehr hängen geblieben?"},"why":"Ihr Kind merkt an sich selbst, dass Konzentration nach Bewegung leichter fällt. Das lässt sich jeden Tag nutzen.","tip":"Nutzen Sie die Erkenntnis: Geben Sie vor Hausaufgaben oder Lesen fünf Minuten zum Bewegen.","need":{"3-5":"ein Kuscheltier, eine Matte","6-8":"ein Puzzle oder Papier und Stifte","9-12":"ein Buch, Timer"},"steps":{"3-5":["Laufen und hüpfen Sie zwei Minuten gemeinsam.","Legen Sie sich auf den Rücken.","Legen Sie Ihrem Kind das Kuscheltier auf den Bauch.","Schauen Sie gemeinsam zu, wie es beim Atmen schaukelt."],"6-8":["Fünf Minuten wildes Spiel.","Fünf Minuten etwas Ruhiges: Puzzle oder Malen.","Fragen Sie: Fällt das Sitzen jetzt leicht?","Vergleichen Sie damit, wie es ohne Aufwärmen ist."],"9-12":["Ihr Kind liest 10 Minuten nach dem Aufwärmen.","Es erzählt nach, was es behalten hat.","An einem anderen Tag liest es 10 Minuten ohne Aufwärmen.","Es vergleicht: Wann ist mehr hängen geblieben?"]}},{"id":"builder-6","scale":"builder","art":"🥄📄🎯","title":"Löffelkatapult","why":"Ihr Kind lernt den Hebel kennen: Eine kleine Verschiebung des Drehpunkts ändert Kraft und Weite.","tip":"Geschossen wird nur mit weichen Papierkugeln und nur von Menschen weg.","need":{"3-5":"ein Plastik- oder Holzlöffel, Papierkugeln, eine Schüssel","6-8":"ein Lineal, ein Bleistift, Papierkugeln, ein Zettel","9-12":"ein Lineal, ein Radiergummi oder Bleistift, Papierkugeln, Maßband, ein Zettel"},"steps":{"3-5":["Knüllen Sie gemeinsam fünf Papierkugeln.","Legen Sie eine Kugel in den Löffel und den Löffel an die Tischkante. Sie halten den Löffel in der Mitte fest, Ihr Kind schlägt auf den Stiel.","Stellen Sie die Schüssel einen Schritt vom Tisch entfernt auf. Trifft es hinein?","Zählen Sie die Treffer von fünf Versuchen."],"6-8":["Legen Sie das Lineal wie eine Wippe auf den Bleistift. Auf ein Ende kommt eine Kugel.","Ihr Kind drückt auf das andere Ende und schaut, wohin die Kugel fliegt.","Schieben Sie den Bleistift näher zur Kugel, dann weiter weg. Drei Starts pro Position.","Wo fliegt die Kugel am weitesten? Ihr Kind erklärt es mit eigenen Worten."],"9-12":["Die Aufgabe: die Position des Drehpunkts für den weitesten Flug finden.","Ihr Kind wählt drei Positionen und macht je drei Starts.","Es trägt die Weiten in eine Tabelle ein.","Es fasst das Ergebnis in einem Satz zusammen und prüft es mit einer vierten Position."]}},{"id":"builder-7","scale":"builder","art":"🪑🛋️⛺","title":"Deckenhöhle","why":"Eine Höhle lehrt, ein Gerüst zu bauen: was trägt, was deckt und wo die Schwachstelle ist.","tip":"Richten Sie ein durchhängendes Dach nicht selbst. Fragen Sie: „Was hält es? Was fehlt?“","need":{"3-5":"zwei Stühle, eine Decke, Kissen","6-8":"Stühle, Decken, Wäscheklammern, Kissen","9-12":"Decken, Wäscheklammern, Stühle, Schnur, ein Blatt Papier"},"steps":{"3-5":["Stellen Sie die Stühle Rücken an Rücken, einen Schritt auseinander.","Legen Sie gemeinsam die Decke darüber.","Ihr Kind bestimmt, wo der Eingang ist, und richtet innen mit Kissen einen Platz ein.","Kriechen Sie zu zweit hinein und lesen Sie ein Buch."],"6-8":["Die Aufgabe: eine Höhle, in die zwei hineinpassen.","Ihr Kind wählt die Stützen und befestigt die Decke mit Wäscheklammern.","Der Test: Kriechen Sie zu zweit hinein. Hält das Dach?","Finden Sie die Schwachstelle und verstärken Sie sie."],"9-12":["Zuerst der Plan: zwei „Zimmer“ und ein Eingang.","Ihr Kind baut nach Plan mit dem, was zu Hause da ist.","Der Test: fünf Minuten zu zweit darin, ohne etwas zu richten.","Was würde es am Plan beim nächsten Mal ändern?"]}},{"id":"builder-8","scale":"builder","art":"✈️📄📏","title":"Rekord-Papierflieger","why":"Ihr Kind ändert ein Detail und misst das Ergebnis. So arbeiten Testingenieurinnen und Testingenieure.","tip":"Starten Sie im Flur und nie in Richtung von Menschen. Ändern Sie immer nur ein Detail.","need":{"3-5":"zwei Blatt Papier","6-8":"drei Blatt Papier, ein Zettel zum Notieren","9-12":"Papier, eine Büroklammer, Maßband, ein Zettel"},"steps":{"3-5":["Falten Sie langsam einen Papierflieger, während Ihr Kind zuschaut.","Ihr Kind lässt ihn dreimal fliegen.","Messen Sie den weitesten Flug in Schritten.","Es malt die Flügel an und startet noch einmal."],"6-8":["Falten Sie gemeinsam zwei verschiedene Modelle: ein schmales und ein breites.","Je drei Starts. Die Weite messen Sie in Schritten.","Welches fliegt weiter? Und welches gerader?","Ihr Kind gibt den Modellen Namen und notiert den Rekord."],"9-12":["Ihr Kind faltet ein Modell und macht drei Vergleichsstarts.","Es ändert ein Detail: eine Büroklammer an der Spitze oder hochgebogene Flügelkanten.","Wieder drei Starts, die Ergebnisse kommen in eine Tabelle.","Der Schluss: Was hat geholfen, was hat gestört und warum?"]}},{"id":"inventor-6","scale":"inventor","art":"🔦🧸👤","title":"Schattenversuche","why":"Ihr Kind entdeckt den Zusammenhang zwischen dem Abstand zum Licht und der Größe des Schattens. Das ist ein erster Schritt zum Verstehen von Ursache und Wirkung.","tip":"Erklären Sie nichts vorab. Fragen Sie: „Wie wird der Schatten größer?“ und lassen Sie es ausprobieren.","need":{"3-5":"eine Taschenlampe, ein Spielzeug, eine Wand","6-8":"eine Taschenlampe, ein Spielzeug, ein Blatt Papier, Bleistift","9-12":"eine Taschenlampe, ein Gegenstand, Lineal, ein Zettel"},"steps":{"3-5":["Machen Sie das Deckenlicht aus und leuchten Sie mit der Taschenlampe auf das Spielzeug vor der Wand.","Suchen Sie gemeinsam den Schatten.","Gehen Sie mit der Lampe näher heran, dann weiter weg. Was ist mit dem Schatten passiert?","Ihr Kind macht selbst einen Riesenschatten und einen Zwergenschatten."],"6-8":["Befestigen Sie das Blatt an der Wand. Ihr Kind stellt das Spielzeug auf und leuchtet.","Zeichnen Sie den Schatten mit dem Bleistift nach.","Die Aufgabe: den Schatten doppelt so groß machen. Was muss sich bewegen?","Zeichnen Sie den neuen Schatten nach und vergleichen Sie."],"9-12":["Ihr Kind stellt die Taschenlampe in drei Abständen zum Gegenstand auf.","Es misst jedes Mal die Höhe des Schattens und schreibt sie auf.","Es sucht die Regel: Was passiert mit dem Schatten, wenn das Licht näher ist?","Es prüft die Regel mit einem vierten Abstand."]}},{"id":"inventor-7","scale":"inventor","art":"🧊🧂⏱️","title":"Rettet den Eiswürfel","why":"Ihr Kind vergleicht Bedingungen und sieht, dass ein Ergebnis eine Ursache hat, die man finden kann.","tip":"Bitten Sie vor dem Versuch um eine Vermutung. Sie stimmt nicht? Das ist das Spannendste.","need":{"3-5":"zwei Eiswürfel, zwei Teller","6-8":"drei Eiswürfel, drei Untertassen, Salz, warmes Wasser","9-12":"Eiswürfel, Alufolie, Stoff, Papier, eine kleine Schachtel, eine Uhr"},"steps":{"3-5":["Legen Sie auf jeden Teller einen Eiswürfel.","Stellen Sie einen an einen warmen, den anderen an einen kühlen Platz.","Fragen Sie: Welcher schmilzt zuerst?","Schauen Sie nach fünf und nach zehn Minuten: Welcher ist kleiner? Das Eis nimmt Ihr Kind nicht in den Mund."],"6-8":["Ihr Kind vermutet, welcher Würfel zuerst schmilzt.","Den ersten bestreut es mit Salz, den zweiten übergießt es mit warmem Wasser, den dritten lässt es in Ruhe.","Es beobachtet zehn Minuten.","Welche Vermutung hat gestimmt? Was hat überrascht?"],"9-12":["Die Aufgabe: einen Eiswürfel so lange wie möglich erhalten.","Ihr Kind denkt sich eine Verpackung aus Dingen im Haushalt aus.","Daneben legt es zum Vergleich einen Eiswürfel ohne Verpackung.","Es stoppt die Zeit bei beiden und erklärt, was gewirkt hat."]}},{"id":"inventor-8","scale":"inventor","art":"☕💡🛠️","title":"Mach es praktischer","why":"Ihr Kind lernt, Unpraktisches zu bemerken und eine Lösung vorzuschlagen. So entstehen Erfindungen.","tip":"Fragen Sie: „Was stört dich an diesem Ding?“ Damit beginnt jede Verbesserung.","need":{"3-5":"eine Tasse oder ein Löffel, ein Blatt Papier, Wachsmalstifte","6-8":"ein Blatt Papier, Stifte","9-12":"Pappe, Klebeband, Schere"},"steps":{"3-5":["Nehmen Sie eine Tasse. Fragen Sie: Was könnte man hinzufügen, damit sie besser wird?","Nehmen Sie jede Idee an: Flügel, Räder, ein zweiter Henkel.","Malen Sie die neue Tasse gemeinsam.","Geben Sie ihr einen Namen."],"6-8":["Ihr Kind wählt etwas, das es jeden Tag benutzt: Schulranzen, Federmäppchen, Bett.","Es sagt, was daran unpraktisch ist.","Es denkt sich drei Verbesserungen aus und zeichnet sie.","Es wählt eine, die sich schon heute umsetzen lässt."],"9-12":["Ihr Kind findet zu Hause etwas Unpraktisches: Kabel verheddern sich, Schuhe liegen herum.","Es überlegt eine Lösung und baut ein Probestück aus Pappe.","Die Familie benutzt es drei Tage.","Es sammelt Rückmeldungen und bessert nach."]}},{"id":"storyteller-6","scale":"storyteller","art":"📷👨‍👩‍👧💭","title":"Geschichte zum Foto","why":"Ihr Kind ergänzt, was nicht im Bild ist: die Ursache und die Fortsetzung. Das ist die Grundlage einer Handlung.","tip":"Fragen Sie „Woran siehst du das?“, damit sich Ihr Kind auf Details im Bild stützt.","need":{"3-5":"ein Familienfoto","6-8":"ein Foto aus einer Zeitschrift oder einem Buch","9-12":"drei Fotos, ein Blatt Papier"},"steps":{"3-5":["Öffnen Sie ein Foto, auf dem Ihr Kind oder vertraute Menschen zu sehen sind.","Fragen Sie: Wer ist das? Was machen sie?","Und was ist danach passiert? Ihr Kind denkt es sich aus.","Erzählen Sie, wie es wirklich war."],"6-8":["Wählen Sie ein Foto mit unbekannten Menschen.","Ihr Kind erzählt, was eine Minute vor der Aufnahme war.","Und was eine Minute danach passiert.","Welches Detail im Foto hat es darauf gebracht?"],"9-12":["Ihr Kind wählt drei Fotos, die nichts miteinander zu tun haben.","Es legt sie in eine Reihe: Anfang, Mitte, Ende.","Zu jedem schreibt es zwei Sätze, sodass eine Geschichte entsteht.","Es ändert die Reihenfolge der Fotos. Wie lautet die neue Geschichte?"]}},{"id":"storyteller-7","scale":"storyteller","art":"👽🪥💬","title":"Erklär es einem Außerirdischen","why":"Wer etwas Einfaches jemandem erklärt, der nichts weiß, lernt, klar zu sprechen.","tip":"Spielen Sie ernsthaft mit. Fragen Sie nach: „Und was ist Wasser?“","need":{"3-5":"ein Kuscheltier","6-8":"eine Zahnbürste oder ein anderer Alltagsgegenstand","9-12":"Timer"},"steps":{"3-5":["Das Kuscheltier kommt von einem anderen Planeten und weiß gar nichts.","Ihr Kind erklärt ihm, was Regen ist.","Das Kuscheltier stellt mit Ihrer Stimme eine Frage.","Danach erklärt Ihr Kind, wie man Suppe isst."],"6-8":["Sie kommen von einem anderen Planeten. Ihr Kind erklärt, wozu eine Zahnbürste da ist.","Die Regel: Das Wort „putzen“ ist verboten.","Stellen Sie zwei ahnungslose Fragen.","Tauschen Sie: Sie erklären, und Ihr Kind fragt nach."],"9-12":["Ein Thema zur Wahl: Internet, Geld oder Schule.","Ihr Kind erklärt es in einer Minute mit einfachen Worten.","Vorher verbieten Sie die drei naheliegendsten Wörter.","Geben Sie wieder, was Sie verstanden haben. Passt es zu dem, was es sagen wollte?"]}},{"id":"storyteller-8","scale":"storyteller","art":"🐱🎩🎶","title":"Reime und Zeilen","why":"Der Reim schult das Ohr für Sprache und lehrt, das treffende Wort zu suchen.","tip":"Ein alberner Unsinnsreim zählt auch. Hauptsache, es macht Spaß.","need":{"3-5":"nichts nötig","6-8":"ein Blatt Papier, Bleistift","9-12":"ein Blatt Papier, Stift"},"steps":{"3-5":["Nennen Sie ein einfaches Wort, zum Beispiel „Haus“.","Suchen Sie gemeinsam Wörter, die ähnlich klingen.","Machen Sie aus zwei davon eine lustige Zeile.","Sprechen Sie sie dreimal im Chor."],"6-8":["Thema: das Lieblingsspielzeug oder ein Haustier.","Ihr Kind sucht zwei Reimpaare.","Es baut daraus vier Zeilen.","Es trägt das Gedicht der Familie mit Betonung vor."],"9-12":["Ihr Kind wählt ein Lieblingsding oder ein Lieblingsessen.","Es schreibt dafür eine Werbung mit vier gereimten Zeilen.","Es denkt sich einen kurzen Slogan aus.","Es liest wie im Radio vor. Sie sagen, ob Sie es kaufen würden und warum."]}},{"id":"artist-6","scale":"artist","art":"🙂✏️🖼️","title":"Porträt","why":"Wer ein Gesicht zeichnet, muss genau hinsehen. So lernt die Hand, dem Auge zu vertrauen.","tip":"Bewerten Sie nicht die Ähnlichkeit. Fragen Sie: „Was ist dir an mir aufgefallen?“","need":{"3-5":"ein Blatt Papier, Wachsmalstifte","6-8":"ein Blatt Papier, ein Filzstift","9-12":"zwei Blätter, Bleistift"},"steps":{"3-5":["Setzen Sie sich Ihrem Kind gegenüber.","Es malt einen großen Kreis: Das ist Ihr Gesicht.","Nennen Sie der Reihe nach: Augen, Nase, Mund, Haare. Es malt sie dazu.","Jetzt malen Sie Ihr Kind, und es sagt Ihnen, was fehlt."],"6-8":["Die Regel: ein Porträt zeichnen, ohne den Stift abzusetzen.","Ihr Kind zeichnet Sie in einer Linie.","Sie zeichnen Ihr Kind genauso.","Suchen Sie in jedem Porträt das gelungenste Detail."],"9-12":["Erstes Porträt: Ihr Kind schaut nur auf Sie, nicht aufs Blatt.","Zwei Minuten, die Linie wird langsam geführt.","Das zweite Porträt ist ein gewöhnliches, ebenfalls zwei Minuten.","Vergleichen Sie: Welches hat mehr Charakter?"]}},{"id":"artist-7","scale":"artist","art":"🤸✨🗿","title":"Figur aus Alufolie","why":"Eine plastische Figur lehrt, eine Form von allen Seiten zu sehen und Bewegung darzustellen.","tip":"Bitten Sie Ihr Kind, die Haltung erst mit dem eigenen Körper zu zeigen. Danach lässt sie sich leichter formen.","need":{"3-5":"Knete oder Salzteig","6-8":"Alufolie","9-12":"Alufolie oder Knete"},"steps":{"3-5":["Rollen Sie gemeinsam drei Kugeln und drei Würste.","Fragen Sie: Welches Tier kann man daraus bauen?","Ihr Kind setzt die Teile zusammen.","Das Tier erzählt mit Ihrer Stimme, wie es heißt."],"6-8":["Reißen Sie ein Stück Alufolie in der Größe eines Blatts Papier ab.","Ihr Kind formt daraus ein Männchen: Kopf, Arme, Beine.","Die Aufgabe: Das Männchen rennt, sitzt oder tanzt.","Sie raten, was es tut."],"9-12":["Die Aufgabe: eine Figur ohne Gesicht, die ein Gefühl zeigt.","Ihr Kind wählt das Gefühl und verrät es Ihnen nicht.","Es formt fünf Minuten.","Sie raten. Was an der Haltung hat es verraten?"]}},{"id":"artist-8","scale":"artist","art":"🪟🌇✏️","title":"Blick aus dem Fenster","why":"Ihr Kind lernt auszuwählen, was ins Bild kommt, und zu bemerken, wie Licht einen vertrauten Ort verändert.","tip":"Fragen Sie: „Was ist hier das Wichtigste?“ Genau das ist Komposition.","need":{"3-5":"ein Fenster, ein Blatt Papier, Wachsmalstifte","6-8":"ein Rahmen aus Pappe oder die Finger, Papier, Stifte","9-12":"zwei Blätter, Bleistift"},"steps":{"3-5":["Schauen Sie eine Minute gemeinsam aus dem Fenster.","Ihr Kind nennt drei Dinge, die es sieht.","Es malt sie auf das Blatt.","Fragen Sie, welches der drei ihm am besten gefällt."],"6-8":["Machen Sie einen Rahmen aus Pappe oder mit den Fingern.","Ihr Kind schaut hindurch aus dem Fenster und wählt einen Ausschnitt.","Es zeichnet nur, was im Rahmen ist.","Es gibt der Zeichnung einen Titel."],"9-12":["Ihr Kind skizziert morgens den Blick aus dem Fenster, fünf Minuten.","Abends macht es eine zweite Skizze vom selben Platz aus.","Es legt beide nebeneinander.","Was hat das Licht verändert: Farben, Schatten, Stimmung?"]}},{"id":"explorer-6","scale":"explorer","art":"🍃🖍️🌳","title":"Abdrücke","why":"Ihr Kind erkundet Oberflächen mit Händen und Augen und lernt, ein Ding an seiner Spur zu erkennen.","tip":"Raten Sie laut und liegen Sie daneben. Lassen Sie sich von Ihrem Kind korrigieren.","need":{"3-5":"Papier, ein Wachsmalstift, ein Baumblatt, ein großer Deckel","6-8":"Papier, ein Wachsmalstift oder ein weicher Bleistift","9-12":"Papier, ein weicher Bleistift, ein Bestimmungsbuch oder eine App"},"steps":{"3-5":["Legen Sie das Baumblatt unter das Papier.","Ihr Kind reibt mit der flachen Seite des Stifts darüber.","Schauen Sie gemeinsam zu, wie das Muster erscheint.","Wiederholen Sie es mit dem Deckel. Worin unterscheiden sich die Abdrücke?"],"6-8":["Beim Spaziergang macht Ihr Kind fünf Abdrücke von verschiedenen Oberflächen.","Rinde, Pflaster, Bank, Blatt, Hauswand.","Zu Hause raten Sie, was was ist.","Es hilft nur mit „wärmer“ und „kälter“."],"9-12":["Ihr Kind macht Rindenabdrücke von drei verschiedenen Bäumen.","Es sammelt von jedem ein Blatt.","Es bestimmt die Bäume mit Buch oder App.","Es beschriftet die Abdrücke und stellt eine Katalogseite zusammen."]}},{"id":"explorer-7","scale":"explorer","art":"🌤️🌧️📝","title":"Wetterbüro","why":"Wetterbeobachtung lehrt, Anzeichen zu bemerken und eine Vorhersage zu machen, die sich überprüfen lässt.","tip":"Die Vorhersage stimmt nicht? Fragen Sie, welches Anzeichen getäuscht hat.","need":{"3-5":"ein Fenster, ein Spielzeug, Kleidung dafür oder ein Stoffrest","6-8":"ein Zettel, Bleistift","9-12":"ein Zettel oder Heft, ein Außenthermometer oder ein Handy"},"steps":{"3-5":["Schauen Sie aus dem Fenster: Sonne, Wolken oder Regen?","Bewegen sich die Äste? Dann ist es windig.","Ihr Kind entscheidet, wie das Spielzeug heute angezogen wird.","Prüfen Sie beim Spaziergang, ob es richtig lag."],"6-8":["Schauen Sie abends gemeinsam in den Himmel.","Ihr Kind schreibt eine Vorhersage für morgen auf: Sonne, Wolken oder Regen.","Morgens prüft es sie.","Drei Tage hintereinander. Wie viele Vorhersagen haben gestimmt?"],"9-12":["Eine Woche lang notiert Ihr Kind zur selben Uhrzeit: Temperatur, Wolken, Wind.","Jeden Abend schreibt es seine eigene Vorhersage für morgen auf.","Es vergleicht sie mit der Vorhersage im Handy und mit dem, was wirklich war.","Am Ende der Woche zählt es, wer genauer war."]}},{"id":"explorer-8","scale":"explorer","art":"👀🧩❔","title":"Was ist anders?","why":"Das Spiel trainiert das visuelle Gedächtnis und den Blick für Details.","tip":"Beginnen Sie leicht. Schwerer wird es erst nach zwei Erfolgen hintereinander.","need":{"3-5":"ein Tablett, fünf große Gegenstände, ein Handtuch","6-8":"ein Zimmer","9-12":"ein Gemälde oder Foto mit vielen Details, ein Zettel"},"steps":{"3-5":["Legen Sie fünf Gegenstände auf das Tablett und benennen Sie sie gemeinsam.","Decken Sie sie mit dem Handtuch zu und nehmen Sie unbemerkt einen weg.","Was fehlt?","Jetzt nimmt Ihr Kind etwas weg, und Sie raten."],"6-8":["Ihr Kind schaut sich das Zimmer eine Minute an und geht hinaus.","Sie ändern drei Dinge: umstellen, wegnehmen, umdrehen.","Es sucht die Veränderungen.","Tauschen Sie die Rollen."],"9-12":["Ihr Kind betrachtet das Bild eine Minute lang.","Nehmen Sie es weg und stellen Sie zehn Fragen zu Details.","Zählen Sie die richtigen Antworten.","Jetzt bereitet es zehn Fragen für Sie vor."]}},{"id":"leader-6","scale":"leader","art":"👨‍👩‍👧🗳️✅","title":"Familienrat","why":"Ihr Kind lernt, alle anzuhören und ein Gespräch zu einer Entscheidung zu führen.","tip":"Sprechen Sie nur, wenn Sie an der Reihe sind. So sieht Ihr Kind, dass die Regeln des Rats für alle gelten.","need":{"3-5":"zwei Möglichkeiten fürs Abendessen oder für einen Spaziergang","6-8":"Timer auf 5 Minuten","9-12":"ein Blatt Papier, Timer"},"steps":{"3-5":["Nennen Sie Ihrem Kind zwei Möglichkeiten.","Es fragt jeden in der Familie, wofür er sich entscheidet.","Es zählt die Stimmen an den Fingern.","Es verkündet das Ergebnis."],"6-8":["Die Frage des Rats: Was machen wir am Wochenende?","Ihr Kind erteilt jedem der Reihe nach das Wort.","Es wiederholt alle Vorschläge laut.","Es lässt abstimmen und verkündet die Entscheidung."],"9-12":["Ihr Kind bereitet drei Themen vor.","Es leitet den Rat: drei Minuten pro Thema.","Es schreibt die Beschlüsse auf und wer wofür zuständig ist.","Nach einer Woche prüft es, was erledigt ist."]}},{"id":"leader-7","scale":"leader","art":"🧸📦🚀","title":"Einsatzleitung","why":"Ihr Kind teilt eine große Aufgabe in Teile und verteilt sie. Das ist die Grundlage des Organisierens.","tip":"Führen Sie jeden Auftrag genau so aus, wie er gesagt wurde. Ein unklarer Auftrag fällt dann sofort auf.","need":{"3-5":"verstreute Spielsachen, Kisten","6-8":"ein Zimmer, Timer auf 10 Minuten","9-12":"ein Blatt Papier, Zutaten für ein einfaches Frühstück"},"steps":{"3-5":["Der Einsatz: die Spielsachen retten und nach Hause bringen.","Ihr Kind leitet: Es sagt, welches Spielzeug wohin kommt.","Sie führen es aus und melden: „Der Teddy ist zu Hause!“","Feiern Sie das Ende des Einsatzes."],"6-8":["Der Einsatz: Ordnung im Zimmer in 10 Minuten.","Ihr Kind teilt das Zimmer in Bereiche und verteilt sie.","Es achtet auf die Zeit und hilft, wo jemand zurückliegt.","Am Ende bedankt es sich beim Team."],"9-12":["Der Einsatz: Frühstück für die Familie in 20 Minuten.","Ihr Kind schreibt eine Aufgabenliste und die Reihenfolge.","Es verteilt die Aufgaben. Am Herd und mit dem Messer arbeitet ein Erwachsener.","Nach dem Frühstück die Auswertung: Was würde es anders verteilen?"]}},{"id":"leader-8","scale":"leader","art":"⚖️🎲🤝","title":"Faire Entscheidung","why":"Ihr Kind lernt, beide Seiten anzuhören und eine Lösung zu finden, die alle annehmen.","tip":"Nehmen Sie die Entscheidung an, auch wenn sie nicht zu Ihren Gunsten ausfällt.","need":{"3-5":"ein einfaches Spiel mit Reihenfolge: Ball oder Bauklötze","6-8":"ein Brettspiel","9-12":"nichts nötig"},"steps":{"3-5":["Ihr Kind achtet auf die Reihenfolge.","Es sagt: „Jetzt bist du dran.“","Drängeln Sie sich einmal vor. Es sollte das bemerken.","Bedanken Sie sich für das faire Spiel."],"6-8":["Heute leitet Ihr Kind das Spiel als Schiedsrichterin oder Schiedsrichter.","Vor dem Spiel sagt es die Regeln an.","Sorgen Sie für einen kleinen Streitfall. Es entscheidet, wer recht hat.","Fragen Sie, warum es so entschieden hat."],"9-12":["Nehmen Sie einen echten kleinen Streit in der Familie.","Ihr Kind hört beide Seiten an, ohne zu unterbrechen.","Es gibt jede Seite so wieder, dass sie zustimmt.","Es schlägt eine Lösung vor, mit der beide leben können."]}},{"id":"helper-6","scale":"helper","art":"🪴💧🐹","title":"Für etwas Lebendiges sorgen","why":"Regelmäßige Pflege einer Pflanze oder eines Haustiers lehrt Verantwortung für jemanden, der auf einen angewiesen ist.","tip":"Erinnern Sie nicht sofort. Fragen Sie: „Wie geht es deiner Pflanze?“","need":{"3-5":"eine Zimmerpflanze, eine kleine Gießkanne, ein feuchtes Tuch","6-8":"eine Pflanze oder ein Haustier, ein Kalenderblatt","9-12":"eine Pflanze oder ein Haustier, ein Buch oder eine Website, ein Zettel"},"steps":{"3-5":["Wählen Sie gemeinsam eine Pflanze aus: Sie gehört jetzt Ihrem Kind.","Es gießt ein wenig.","Es wischt ein Blatt mit dem Tuch ab.","Fragen Sie: Was mag die Pflanze?"],"6-8":["Ihr Kind wählt, um wen es sich eine Woche kümmert.","Sie finden gemeinsam heraus, was nötig ist und wie oft.","Es hakt jeden Tag im Kalender ab, was erledigt ist.","Am Ende der Woche: Was hat sich verändert?"],"9-12":["Ihr Kind findet heraus, was sein Schützling braucht: Licht, Wasser, Futter.","Es schreibt einen Merkzettel für die Familie.","Es ist eine Woche für die Pflege verantwortlich.","Danach erzählt es, was am schwersten war."]}},{"id":"helper-7","scale":"helper","art":"👂💬❤️","title":"Ich höre dir zu","why":"Zuhören, ohne zu unterbrechen, und das Gehörte wiedergeben: Darauf beruht Freundschaft.","tip":"Erzählen Sie kurz und von Echtem. Kinder spüren, wenn eine Geschichte erfunden ist.","need":{"3-5":"nichts nötig","6-8":"Timer auf 2 Minuten","9-12":"nichts nötig"},"steps":{"3-5":["Erzählen Sie in drei Sätzen, wie Ihr Tag war.","Ihr Kind wiederholt: „Du hast heute …“","Fragen Sie: Was glaubst du, war ich fröhlich oder traurig?","Tauschen Sie: Jetzt erzählt Ihr Kind."],"6-8":["Sie erzählen zwei Minuten von Ihrem Tag.","Ihr Kind hört zu, ohne zu unterbrechen.","Es stellt eine Frage.","Es gibt das Wichtigste wieder. Sagen Sie, ob es richtig verstanden hat."],"9-12":["Ihr Kind fragt jemanden in der Familie, wie der Tag war.","Es stellt drei Nachfragen.","Es benennt das Gefühl: „Das klingt, als hättest du dich geärgert.“","Es fragt, ob das stimmt."]}},{"id":"helper-8","scale":"helper","art":"💛📝😊","title":"Freundliche Worte","why":"Ihr Kind lernt, das Gute an anderen zu bemerken und es konkret auszusprechen.","tip":"Machen Sie es vor: Sagen Sie Ihrem Kind, was genau ihm heute gut gelungen ist.","need":{"3-5":"das gemeinsame Abendessen","6-8":"Zettel, Bleistift","9-12":"ein Zettel oder Notizen im Handy"},"steps":{"3-5":["Beim Abendessen sagt Ihr Kind jedem etwas Nettes.","Helfen Sie mit dem Anfang: „Mir gefällt, wie du …“","Jeder antwortet mit „Danke“.","Zum Schluss bekommt es selbst ein freundliches Wort."],"6-8":["Ihr Kind schreibt jedem in der Familie einen Zettel.","Auf jedem steht etwas Konkretes: „Danke, dass du mein Fahrrad repariert hast.“","Es versteckt die Zettel dort, wo sie gefunden werden.","Sprechen Sie abends darüber, wer was gefunden hat."],"9-12":["Im Lauf des Tages bemerkt Ihr Kind drei gute Taten anderer Menschen.","Es notiert, wer was getan hat.","Abends sagt oder schreibt es jedem davon.","Sprechen Sie darüber: Wie haben die Menschen reagiert?"]}},{"id":"mover-6","scale":"mover","art":"🧘📚〰️","title":"Halt das Gleichgewicht","why":"Gleichgewicht hängt mit Aufmerksamkeit und Haltung zusammen und lässt sich im Spiel gut üben.","tip":"Stellen Sie sich daneben auf ein Bein. Gemeinsam wackeln macht mehr Spaß.","need":{"3-5":"ein Seil oder ein Streifen Klebeband am Boden, ein Kuscheltier","6-8":"Stoppuhr","9-12":"ein Buch, Stoppuhr, ein Zettel"},"steps":{"3-5":["Legen Sie eine Linie auf den Boden.","Ihr Kind geht mit ausgebreiteten Armen darauf entlang.","Jetzt mit dem Kuscheltier auf dem Kopf.","Gehen Sie hinterher und lassen Sie das Kuscheltier fallen. Ihr Kind darf lachen."],"6-8":["Ihr Kind steht auf einem Bein. Stoppen Sie die Zeit.","Dann auf dem anderen. Welches steht sicherer?","Jetzt mit geschlossenen Augen, Sie stehen daneben.","Notieren Sie die drei Ergebnisse."],"9-12":["Ihr Kind geht mit einem Buch auf dem Kopf durchs Zimmer.","Schwerer: in die Hocke gehen und aufstehen, ohne es zu verlieren.","Es denkt sich eine Strecke mit Kurve aus.","Drei Versuche auf Zeit. Es notiert den Rekord."]}},{"id":"mover-7","scale":"mover","art":"🧦🧺🎯","title":"Zielwurf","why":"Zielwerfen schult das Augenmaß und das Gefühl für Kraft.","tip":"Geworfen wird nur Weiches: zusammengerollte Socken oder Papierkugeln.","need":{"3-5":"ein Korb oder eine Wanne, fünf Paar zusammengerollte Socken","6-8":"ein Korb, Socken, ein Zettel","9-12":"ein Korb, Socken, ein Zettel"},"steps":{"3-5":["Stellen Sie den Korb zwei Schritte entfernt auf.","Ihr Kind wirft fünf Socken.","Zählen Sie die Treffer laut.","Gehen Sie einen Schritt zurück und wiederholen Sie es."],"6-8":["Markieren Sie drei Linien: nah, mittel, weit.","Ein Treffer bringt je nach Linie 1, 2 oder 3 Punkte.","Jeder hat sechs Würfe. Die Linie wählt jeder selbst.","Zählen Sie die Punkte. Welche Linie lohnt sich am meisten?"],"9-12":["Ihr Kind denkt sich ein Turnier aus: Regeln, Punkte, Zahl der Runden.","Eine Runde wird mit der schwächeren Hand geworfen.","Es führt die Tabelle.","Nach dem Turnier ändert es eine Regel, damit es spannender wird."]}},{"id":"mover-8","scale":"mover","art":"🪞🙆🎵","title":"Spiegel","why":"Bewegungen nachzumachen trainiert Aufmerksamkeit, Koordination und das Bewegungsgedächtnis.","tip":"Bewegen Sie sich langsam. Es geht ums Nachmachen, nicht ums Verwirren.","need":{"3-5":"freier Platz","6-8":"freier Platz","9-12":"Timer, Musik"},"steps":{"3-5":["Stellen Sie sich Ihrem Kind gegenüber.","Heben Sie langsam einen Arm. Es macht es nach wie ein Spiegel.","Nehmen Sie eine Beuge, einen Schritt und eine Kniebeuge dazu.","Jetzt führt Ihr Kind, und Sie sind der Spiegel."],"6-8":["Zeigen Sie eine Folge aus vier Bewegungen.","Ihr Kind wiederholt sie aus dem Gedächtnis.","Es fügt eine fünfte Bewegung hinzu, Sie wiederholen die ganze Folge.","Machen Sie weiter, bis jemand durcheinanderkommt."],"9-12":["Ihr Kind stellt ein Bewegungsprogramm aus sechs Übungen für drei Minuten zusammen.","Es sucht passende Musik aus.","Es leitet das Programm für die Familie an.","Es fragt, welche Übung bleiben und welche ersetzt werden soll."]}}],"safety":"Die Aufgaben werden zusammen mit einem Erwachsenen gemacht. Schere, Messer und Heißes übernimmt der Erwachsene."};
